# Пул процессов для kenburns()/video_render() (НЕ parallax_kenburns() — та
# намеренно остаётся последовательной в главном процессе, см. main()).
# Почему процессы, а не потоки: полная изоляция между воркерами (ни общего
# состояния, ни вопроса потокобезопасности torch-модели при конкурентных
# вызовах — вопрос, на который я не готов ответить "да" не проверив, а
# проверять на живом многочасовом рендере не буду); почему НЕ тянет за
# собой дублирование depth-модели в памяти: torch/transformers загружаются
# ЛЕНИВО (см. get_depth_model/get_clip_model — импорт внутри функции, не на
# уровне модуля) и только в ГЛАВНОМ процессе при рендере параллакс-кадра —
# воркеры этот код вообще не исполняют, значит и не грузят. -threads на
# каждый ffmpeg-вызов воркера — иначе N параллельных процессов, каждый сам
# по себе многопоточный, начнут толкаться за одни и те же ядра и просадят
# эффект (проверено рассуждением: libx264 -preset fast по умолчанию берёт
# все доступные ядра сам). RENDER_POOL_WORKERS оставляет минимум 1 ядро
# главному процессу (параллакс + оркестрация), не отправляет туда весь nproc.
RENDER_POOL_ENABLED = os.environ.get("RENDER_PARALLEL", "1") != "0"


def _default_render_workers():
    """CPU-aware пол уже был (nproc-1, минимум 1 ядро оставлен главному
    процессу под параллакс/оркестрацию) — этого недостаточно на машине с
    МНОГО ядер, но МАЛО RAM: N параллельных ffmpeg-процессов (каждый —
    свой 8000x4500 холст под zoompan, см. kenburns()) может честно вызвать
    OOM раньше, чем упрутся в CPU. Грубая (не Windows — Linux/macOS-only,
    тот же принцип отката, что уже использует log_render_diagnostics)
    оценка доступной памяти: ~700MB на воркер с запасом, не точная бухгалтерия,
    а защита от самого частого правдоподобного сценария (мало RAM + много
    ядер в облачном контейнере). Сбой определения ресурсов -> тихий откат
    на прежний чисто CPU-based расчёт, ноль регресса."""
    cpu_based = max(1, (os.cpu_count() or 4) - 1)
    try:
        with open("/proc/meminfo", encoding="utf-8") as f:
            for line in f:
                if line.startswith("MemAvailable:"):
                    avail_mb = int(line.split()[1]) / 1024
                    mem_based = max(1, int(avail_mb // 700))
                    return max(1, min(cpu_based, mem_based))
    except Exception:
        pass
    return cpu_based


def _render_workers_from_env():
    """RENDER_WORKERS=0/мусор раньше роняли ProcessPoolExecutor ValueError уже
    в середине main() (аудит 04.09) — клэмп к [1, cpu]."""
    try:
        n = int(os.environ.get("RENDER_WORKERS", "") or _default_render_workers())
    except ValueError:
        n = _default_render_workers()
    return max(1, min(n, max(1, os.cpu_count() or 4)))


RENDER_POOL_WORKERS = _render_workers_from_env()


