COLOR_META_ARGS = ["-color_primaries", "bt709", "-color_trc", "bt709", "-colorspace", "bt709",
                    "-color_range", "tv"]


# ^ -color_range tv добавлен по прямому запросу пользователя ("копни глубже
# на Rec.709") — исследовано, ПРОВЕРЕНО ВЖИВУЮ, не гипотеза. Реальные
# скачанные Pexels-исходники (см. media/pexels_video_cache) РЕАЛЬНО несут
# разные color_range: часть tv (limited, 16-235), часть pc/yuvj420p (full,
# 0-255) — подтверждено ffprobe на кадрах этого канала. НО: прямой closed-
# loop тест (pc-источник -> сборочная цепочка с уже существующим
# `-pix_fmt yuv420p10le` из CLIP_PIX_ARGS -> декод финального клипа с учётом
# его собственного тега -> сравнение с оригиналом) показал, что явный
# `-pix_fmt yuv420p10le` УЖЕ заставляет ffmpeg корректно, а не просто
# переклеивая ярлык, пересчитывать значения в tv-диапазон независимо от
# входного pc/tv — расхождение среднего по каналам <0.4/255, полный 0-255
# охват воспроизведён верно (не "смятый" в 16-235 без пересчёта). То есть
# теоретический баг (разные клипы эпизода после сборки визуально "спорят"
# по уровню чёрного/белого) на практике НЕ воспроизводится на этом коде —
# `-pix_fmt yuv420p10le`/`yuv420p`, УЖЕ стоявший на каждом libx264-выходе
# (CLIP_PIX_ARGS/xfade_chain), уже был достаточной защитой. Добавка здесь —
# чистое ужесточение (explicit лучше implicit: явный тег не зависит от
# будущей, потенциально забытой смены pix_fmt) — проверено, что она НЕ
# меняет итоговый вывод (тот же тег `tv`, тот же результат и до, и после,
# на реальных pc- и tv-источниках).
# 10-бит ТОЛЬКО на промежуточных клипах (kenburns/video_render/
# parallax_kenburns) — у нас две генерации перекодирования (клип -> общий
# xfade-проход), и 8-бит на КАЖДОЙ из них копит собственную ошибку
# квантования (видно на тёмных градиентах — deband лечит следствие, не
# причину). xfade_chain() и pad_to_length() ОСТАЮТСЯ на yuv420p (8-бит) —
# это финальный формат поставки (-c:v copy на финальном муксе копирует
# ИМЕННО их выход без изменений), 10-бит H.264 не универсально безопасен
# для доставки на YouTube. ffmpeg сам понижает точность при декодировании
# 10-битных клипов в 8-битный xfade-выход — обычный смешанный pipeline,
# ничего специального делать не нужно на стороне master-прохода.
CLIP_PIX_ARGS = ["-pix_fmt", "yuv420p10le", "-profile:v", "high10"]


