CONTENT_ALT_BLOCKLIST = tuple(CHANNEL_PROFILE.get("content_alt_blocklist", _CONTENT_ALT_BLOCKLIST_DEFAULT))


STAT_ACCENT = "0xC8102E"   # акцентный красный, CHANNEL.md house style


# D4: печатная машинка на 5-м варианте плашки (variant 4 из 5) — round-robin
# stat_variant % 5 уже даёт "не постоянно всегда" бесплатно (1 из 5 появлений
# цифры/даты в ролике), без отдельной классификации "это дата или нет" —
# [stat:...] и так по смыслу ВСЕГДА число/дата (см. ЧАСТЬ 9 script.txt),
# отдельный детектор не нужен. Тайминг посимвольного появления — константа,
# используется И в drawtext (визуал), И в main() при сборе таймкодов для
# звука печатной машинки (add_typewriter_clicks) — ОДНА и та же величина,
# иначе визуал и звук разъедутся по скорости печати.
TYPEWRITER_CHAR_DUR = 0.075


# Библиотека из 8 РЕАЛЬНЫХ отдельных ударов клавиш (не один клип, повторённый
# клонштампом на каждый символ — на реальной записи разные удары звучат чуть
# по-разному, один и тот же сэмпл на каждый символ читался механически,
# "не как в живой записи", по прямой обратной связи пользователя). Извлечены
# из присланной пользователем записи (scripts/generate — нет, это ручное
# разовое извлечение, см. коммит) — каждый нормализован к своему пику
# отдельно (не общий loudnorm), сохраняя естественный разброс громкости
# между разными ударами.
KEYBOARD_CLICKS_DIR = os.path.join(os.path.dirname(os.path.dirname(os.path.abspath(__file__))),
                                    "assets", "sfx", "keyboard_clicks")


# Библиотека настоящих записей машинки (CC0, отобраны моделями) — первой;
# старые click_*.flac неизвестного происхождения остаются запасным путём.
KEYBOARD_CLICK_PATHS = (library_sounds("sfx", "typewriter")
                        or sorted(glob.glob(os.path.join(KEYBOARD_CLICKS_DIR, "click_*.flac"))))


TYPEWRITER_CLICK_ENABLED = feature_flags.enabled("TYPEWRITER_CLICKS") and bool(KEYBOARD_CLICK_PATHS)


TYPEWRITER_CLICK_GAIN_DB = -6.0


# Запас в конце блока при пересчёте момента плашки. У машинки он большой
# (1.2с) — ей нужно место на саму посимвольную печать; тику хватает его
# собственной длины с небольшим запасом.
STAT_REVEAL_TAIL_TYPEWRITER_SEC = 1.2


STAT_REVEAL_TAIL_TICK_SEC = 0.3


def stat_reveal_moment(stat_delay, real_dur, tail_margin):
    """Момент появления плашки на АУДИО-шкале (смещение от начала блока).

    stat_delay считается от ДЛИТЕЛЬНОСТИ КЛИПА (durs[i], в неё входит бюджет
    xfade), а любой звук живёт на шкале sub_starts/sub_baseline — той же,
    что субтитры. Складывать одно с другим напрямую значит получить
    смещение, которого на звуковой дорожке нет. Машинка это уже учитывала
    инлайн; функция вынесена, чтобы второй потребитель (тик появления
    плашки) не завёл вторую, слегка другую копию того же пересчёта — ровно
    тот класс расхождения, ради которого рядом уже стоит
    typewriter_reveal_timing().
    """
    return max(0.0, min(float(stat_delay), max(0.0, float(real_dur) - float(tail_margin))))


def typewriter_reveal_timing(n_chars, delay, dur, fin_dur=0.25, hold_margin=0.5):
    """Общая математика тайминга посимвольного появления — используется И в
    add_overlays() (визуал, локальное время клипа), И в main() при сборе
    таймкодов звука (реальное абсолютное время ролика) — ОДНА функция, чтобы
    визуал и звук печатной машинки не могли разъехаться по скорости из-за
    двух независимо подправленных копий одной и той же формулы клэмпа."""
    hold = max(delay + fin_dur, dur - hold_margin)
    cd = TYPEWRITER_CHAR_DUR
    if n_chars > 0 and delay + n_chars * cd > hold:
        cd = max(0.02, (hold - delay) / n_chars)
    return hold, cd


# Геометрические нормы экранного текста (сверка 13.09, отраслевой стандарт
# титров для 1920x1080). Варианты 0-2 им и так соответствовали, вариант 3
# нарушал все три сразу — см. комментарий у него.
#  * поле от края — не меньше 5% ширины кадра (96 px);
#  * низ текста — выше зоны, где YouTube рисует полосу перемотки и кнопки
#    (нижние ~18% кадра); на телефоне они всплывают от каждого касания.
STAT_SAFE_MARGIN_PX = 96


STAT_CORNER_RULE_BOTTOM_PX = 200   # подчёркивание: 1080-200 = 880, верхняя граница зоны плеера


STAT_CORNER_TEXT_BOTTOM_PX = 252   # текст над подчёркиванием, тем же шагом


def pick_stat_variant(stat_variant, media_path=None):
    """D5: среди "статичных" оформлений плашки (0/1/2/3 — баннер-бокс/
    крупный центр без бокса/боковой акцент/мелкий угол) выбор не чисто по
    кругу, а с поправкой на РЕАЛЬНЫЙ контраст/плотность кадра под ней:
    - плотный кадр (busy>0.55, много локальных перепадов — макро/деталь) ->
      мелкий угловой (3), крупная плашка перекрыла бы сюжет;
    - малоконтрастный фон (узкий диапазон белая-чёрная точка) -> крупный
      центральный текст без бокса (1) читается безопасно, бокс тут не нужен;
    - просторный И контрастный кадр -> боковой акцент (2), есть настоящее
      негативное пространство под полосу+текст;
    - смешанный случай -> классический баннер с боксом (0), самый
      универсально безопасный (бокс сам создаёт контраст, не полагается на
      то, что уже есть в кадре).
    media_path=None (видео-клип или PIL/np недоступны) -> откат на прежний
    чистый round-robin (%4) — не регрессия, а прежнее поведение."""
    if media_path is None:
        return stat_variant % 4
    try:
        busy = estimate_busyness(media_path)
        levels = measure_levels(media_path)
        contrast = (levels[1] - levels[0]) if levels else 0.5
    except Exception:
        return stat_variant % 4
    if busy > 0.55:
        return 3
    if contrast < 0.35:
        return 1
    if busy < 0.25 and contrast > 0.55:
        return 2
    return 0


def add_overlays(vf_base, dur, title=None, stat=None, stat_variant=0, stat_delay=0.0, media_path=None):
    """Титр секции (низ кадра, слайд+fade первые ~2.5с, фирменный дисплейный
    шрифт) + цифровая плашка. Общий код для фото и видео-стока. Обычный
    fade раньше был самым узнаваемым штампом автослайдшоу — слайд добавляет
    "кто-то это анимировал руками".

    Плашка (2.2): раньше ОДИН и тот же красный баннер на каждую цифру за
    ролик — после 3-4 повторов за 16 минут читается как "шаблон программы",
    не дизайнерское решение. 4 варианта оформления, чередуются по позиции
    цифры в ролике (main() считает running-индекс): классический баннер /
    крупное число по центру без плашки / боковой акцент с полосой / мелкий
    текст в углу с подчёркиванием."""
    vf = vf_base
    # Титр раздела — вторичный уровень иерархии (Montserrat): это подпись,
    # не "геройский" факт-баннер — жирный, но не такой кричащий, как Benzin
    # на цифрах-доказательствах (stat ниже). Один и тот же шрифт на оба
    # уровня раньше читался как "программа так рисует", не решение монтажёра.
    if title and FONT_SECONDARY_PATH:
        hold = min(2.5, dur * 0.6)
        fin = max(0.3, hold * 0.3)
        text = title.upper() if FONT_IS_DISPLAY else title
        safe = escape_drawtext(text)
        fs = 46 if FONT_IS_DISPLAY else 54
        vf += (f",drawtext=fontfile='{ffmpeg_filter_path(FONT_SECONDARY_PATH)}':text='{safe}':"
               f"fontcolor=white:fontsize={fs}:borderw=3:bordercolor=black@0.8:"
               f"x=(w-text_w)/2:"
               f"y='h-180+(1-min(t/{fin:.2f}\\,1))*36':"
               f"alpha='if(lt(t\\,{fin:.2f})\\,t/{fin:.2f}\\,"
               f"if(lt(t\\,{hold:.2f})\\,1\\,max(0\\,1-(t-{hold:.2f})/0.4)))'")
    if stat and FONT_PATH:
        fin_dur = 0.25
        # Плашка раньше ВСЕГДА стартовала от t=0 клипа — независимо от того,
        # где внутри фразы реально произносится число (см. stat_word_pos в
        # parse_blocks/split_long_blocks). Цифра появлялась на экране
        # заметно раньше, чем её произносили. delay — момент внутри клипа,
        # когда число уже озвучено; clamp оставляет минимум ~1.2с на сам
        # fade-in/hold/fade-out, даже если delay пришёлся почти на конец
        # клипа (не даём плашке исчезнуть, не успев появиться). Резерв —
        # STAT_PLATE_TAIL_SEC (читаемые 1.2с ПЛЮС длительность уходящего
        # xfade, см. её комментарий: на готовом файле плашка жила 0.5с
        # вместо 1.2 именно потому, что резерв считался в шкале клипа).
        delay = max(0.0, min(stat_delay, dur - STAT_PLATE_TAIL_SEC))
        fin = delay + fin_dur
        hold = max(fin, dur - 0.5)
        text = stat.upper() if FONT_IS_DISPLAY else stat
        safe = escape_drawtext(text)
        alpha = (f"if(lt(t\\,{delay:.2f})\\,0\\,"
                 f"if(lt(t\\,{fin:.2f})\\,(t-{delay:.2f})/{fin_dur:.2f}\\,"
                 f"if(lt(t\\,{hold:.2f})\\,1\\,max(0\\,1-(t-{hold:.2f})/0.4))))")
        # D4: печатная машинка — фиксированный round-robin слот "не всегда"
        # (1 из 5 появлений цифры/даты), независимо от D5 ниже. D5: остальные
        # 4/5 появлений выбирают оформление по контрасту кадра, не по кругу.
        variant = 4 if stat_variant % 5 == 4 else pick_stat_variant(stat_variant, media_path)
        if variant == 0:
            # Классический баннер — верх кадра, слайд сверху.
            fs = 58 if FONT_IS_DISPLAY else 64
            vf += (f",drawtext=fontfile='{ffmpeg_filter_path(FONT_PATH)}':text='{safe}':"
                   f"fontcolor=white:fontsize={fs}:"
                   f"box=1:boxcolor={STAT_ACCENT}@0.92:boxborderw=18:"
                   f"x=(w-text_w)/2:"
                   f"y='110-(1-max(0\\,min((t-{delay:.2f})/{fin_dur:.2f}\\,1)))*26':"
                   f"alpha='{alpha}'")
        elif variant == 1:
            # Крупное число по центру кадра — без плашки, тень вместо box.
            fs = 96 if FONT_IS_DISPLAY else 108
            vf += (f",drawtext=fontfile='{ffmpeg_filter_path(FONT_PATH)}':text='{safe}':"
                   f"fontcolor=white:fontsize={fs}:"
                   f"shadowcolor=black@0.85:shadowx=4:shadowy=4:"
                   f"borderw=2:bordercolor=black@0.6:"
                   f"x=(w-text_w)/2:y=(h-text_h)/2:"
                   f"alpha='{alpha}'")
        elif variant == 2:
            # Боковой акцент — число слева, вертикальная полоса рядом.
            fs = 62 if FONT_IS_DISPLAY else 68
            # drawbox: w/h в x/y-выражениях ссылаются на СОБСТВЕННЫЕ параметры
            # бокса (w=8, h=160), не на кадр — иначе бы (h-160)/2 = 0
            # (самоссылка h=160-160=0), поймано на реальном рендере (полоса
            # уезжала в самый верх кадра). ih/iw — явно "кадр", не бокс.
            vf += (f",drawbox=x=100:y=(ih-160)/2:w=8:h=160:"
                   f"color={STAT_ACCENT}@0.92:t=fill:"
                   f"enable='between(t\\,{delay:.2f}\\,{hold:.2f})'"
                   f",drawtext=fontfile='{ffmpeg_filter_path(FONT_PATH)}':text='{safe}':"
                   f"fontcolor=white:fontsize={fs}:"
                   f"shadowcolor=black@0.8:shadowx=3:shadowy=3:"
                   f"x=130:y=(h-text_h)/2:"
                   f"alpha='{alpha}'")
        elif variant == 3:
            # Минимальный — текст в нижнем правом углу, подчёркивание. По
            # смыслу подпись, не геройская цифра — вторичный шрифт, но
            # реальная жалоба (скриншот пользователя): на практике читалась
            # как "слишком мелкая и незаметная" на фоне живой картинки —
            # 34-38px терялись рядом с деталями кадра. Крупнее + тёмная
            # подложка под текст для контраста (не превращаем в баннер
            # variant 0 — подложка полупрозрачная и только под текстом, не
            # во весь угол), позиция и логика (right-aligned, подчёркивание)
            # не менялись — только заметность.
            # Кегль/поля/высота приведены к тем же нормам, что у вариантов
            # 0-2 (найдено сверкой геометрии 13.09 — вариант 3 нарушал ТРИ
            # нормы сразу, остальные три варианта ни одной):
            #  * кегль был 46-52 при отраслевой норме от 54 (5% высоты
            #    кадра) — на телефоне это уже нечитаемо. Рядом в истории
            #    правок стоит жалоба пользователя "слишком мелкая и
            #    незаметная", по которой кегль подняли с 34-38 до 46-52 —
            #    то есть проблему знали, но до нормы так и не довели;
            #  * правый отступ был 70 при норме не меньше 96 (5% ширины) —
            #    текст прижимался к самому краю;
            #  * САМОЕ ВАЖНОЕ: текст стоял на y=h-140 (=940 в кадре 1080),
            #    а подчёркивание на ih-88 (=992) — это ровно та зона, где
            #    YouTube рисует полосу перемотки и кнопки. На телефоне они
            #    всплывают от каждого касания и перекрывают подпись.
            #    STAT_CORNER_BOTTOM_Y держит низ подчёркивания выше этой
            #    зоны, текст поднимается над ним.
            fs = 56 if FONT_IS_DISPLAY else 60
            vf += (f",drawtext=fontfile='{ffmpeg_filter_path(FONT_SECONDARY_PATH)}':text='{safe}':"
                   f"fontcolor=white:fontsize={fs}:"
                   f"box=1:boxcolor=black@0.5:boxborderw=12:"
                   f"borderw=2:bordercolor=black@0.7:"
                   f"x=w-text_w-{STAT_SAFE_MARGIN_PX}:y=h-{STAT_CORNER_TEXT_BOTTOM_PX}:"
                   f"alpha='{alpha}'"
                   f",drawbox=x=iw-300:y=ih-{STAT_CORNER_RULE_BOTTOM_PX}:w=240:h=4:"
                   f"color={STAT_ACCENT}@0.92:t=fill:"
                   f"enable='between(t\\,{delay:.2f}\\,{hold:.2f})'")
        else:
            # D4: печатная машинка — сверено с референсом пользователя
            # (архивная аэросъёмка, дата "12.09.2020"): НЕ крупный "геройский"
            # центр кадра (как было раньше), а скромная подпись в нижней
            # трети — субтильный вес, тонкая тень вместо жирного борда, ближе
            # к "архивной датировке кадра", чем к рекламному баннеру. По X
            # оставлен центр (не копируем точный сдвиг референса влево — тот
            # кадр 9:16 с другим соотношением сторон, а текст variant 4 может
            # быть разной длины/языка, центр — единственное универсально
            # безопасное положение по горизонтали).
            # Символы появляются один за другим (та же ставка
            # TYPEWRITER_CHAR_DUR, что задаёт таймкоды звука в
            # main()/add_typewriter_clicks), после полного текста — обычная
            # задержка и fade-out, как у остальных вариантов. Цепочка
            # drawtext: filter k показывает text[:k+1] ТОЛЬКО в своём окне
            # [delay+k*cd, delay+(k+1)*cd) — сменяется следующим, длиннее на
            # один символ; последний остаётся до конца hold+fade-out.
            n_chars = len(text)
            _, cd = typewriter_reveal_timing(n_chars, delay, dur)
            fs = 56 if FONT_IS_DISPLAY else 62
            for k in range(n_chars):
                sub = escape_drawtext(text[:k + 1])
                seg_start = delay + k * cd
                # Аудит 04.09: enable обрывался ровно на hold, а alpha гасит
                # текст на hold..hold+0.4 — fade-out никогда не рисовался, текст
                # исчезал скачком. Окно enable покрывает весь fade.
                seg_end = min(dur, hold + 0.4) if k == n_chars - 1 else delay + (k + 1) * cd
                seg_alpha = alpha if k == n_chars - 1 else "1"
                vf += (f",drawtext=fontfile='{ffmpeg_filter_path(FONT_PATH)}':text='{sub}':"
                       f"fontcolor=white:fontsize={fs}:"
                       f"shadowcolor=black@0.7:shadowx=1:shadowy=1:"
                       f"x=(w-text_w)/2:y=h*0.78-text_h/2:"
                       f"enable='between(t\\,{seg_start:.3f}\\,{seg_end:.3f})':"
                       f"alpha='{seg_alpha}'")
    return vf


CAPTION_FONT_SIZE = 76   # D2: крупные кинетические слова-акценты хука, Benzin-ExtraBold


def add_kinetic_captions(vf, captions):
    """D2: кинетические подписи хука — по одному слову крупным фирменным
    шрифтом (FONT_PATH), синхронно с РЕАЛЬНЫМ посимвольным таймингом
    произношения (см. load_hook_word_timings/hook_captions_for_block — тот
    же alignment.csv, что и везде в пайплайне, не оценка по words/wps).
    Только ХУК (main() зовёт это только для HOOK-блоков) — приём крупных
    слов-акцентов для самых первых секунд удержания, не постоянный субтитр
    на весь ролик (тот — write_subtitles(), полноразмерные описательные
    субтитры, другая задача).

    Позиция (2.6, было h*0.66 — реальная жалоба: слишком по центру кадра,
    мешает смотреть картинку): write_subtitles() пишет ТОЛЬКО отдельный
    subtitles.srt для загрузки на YouTube, в кадр НЕ вшивается — "дно кадра
    уже занято субтитрами" было неверно с самого начала, реального
    конкурента внизу нет. Единственные соседи внизу — плашка-цифра (2.2):
    variant 4 (typewriter, add_overlays) сидит на y=h*0.78 по центру,
    variant 3 — мелкая подпись в правом нижнем углу (y=h-110). Стандартная
    для горизонтального ролика зона субтитров — нижняя треть, ближе к низу,
    чем к центру, но с запасом НАД variant 4, чтобы два текстовых слоя не
    накладывались, если в одном клипе одновременно и цифра, и кинетическое
    слово хука."""
    if not captions or not FONT_PATH:
        return vf
    for word, start, end in captions:
        text = word.upper() if FONT_IS_DISPLAY else word
        safe = escape_drawtext(text)
        if not safe:
            continue
        vf += (f",drawtext=fontfile='{ffmpeg_filter_path(FONT_PATH)}':text='{safe}':"
               f"fontcolor=white:fontsize={CAPTION_FONT_SIZE}:"
               f"shadowcolor=black@0.85:shadowx=3:shadowy=3:"
               f"borderw=2:bordercolor=black@0.6:"
               f"x=(w-text_w)/2:y=h*0.73-text_h/2:"
               f"enable='between(t\\,{start:.3f}\\,{end:.3f})'")
    return vf


def image_size_as_rendered(path):
    """(ширина, высота) фото ТАК, как его отдаст ffmpeg. Аудит 04.09
    (воспроизведено: JPEG 1200x600 с EXIF Orientation=6): PIL .size даёт
    сырые размеры без учёта EXIF, ffmpeg 6.x (и cv2.imread) автоповорачивают
    кадр — геометрия кропа считалась для 1200x600, а фильтр получал 600x1200,
    и scale=nw:nh растягивал портретное фото с телефона в пропорцию 4:1."""
    with PILImage.open(path) as img:
        try:
            return PILImageOps.exif_transpose(img).size
        except Exception:
            return img.size


def ffmpeg_filter_path(path):
    """Путь для ЗНАЧЕНИЯ опции фильтра (fontfile=…). Аудит 04.09
    (воспроизведено на ffmpeg 6.1): парсер опций режет значение по ':' —
    Windows-путь 'C:\\…\\Benzin.ttf' превращается в fontfile='C', остаток
    уходит в позиционный параметр, ffmpeg молча берёт fontconfig-дефолт с
    rc=0 — на основной платформе пользователя вся типографика титров/плашек
    тихо подменялась системным шрифтом. Обратные слэши -> прямые (ffmpeg их
    понимает на Windows), двоеточие -> '\\:'. На POSIX-путях без ':' —
    без изменений."""
    return str(path).replace("\\", "/").replace(":", "\\:")


def kb_hash_choices(photo):
    """Кандидаты зума/пана по хэшу файла — детерминированно, но БЕЗ памяти о
    соседних клипах (это даёт anti-repetition в main(), см. pick_no_repeat)."""
    h = int(hashlib.md5(photo.encode()).hexdigest()[:8], 16)
    zoom_in = bool(h & 1)
    pan_dir = PAN_DIRECTIONS[(h >> 1) % len(PAN_DIRECTIONS)]
    return h, zoom_in, pan_dir


@memoize_by_frame
def estimate_busyness(photo_path):
    """Грубая мера "тесноты" кадра без depth-модели — просто плотность
    перепадов яркости на уменьшенной копии. Не настоящая детекция крупности
    плана, но дешёвый прокси: у тесного/плотного кадра (уже крупный план)
    перепадов много на каждый пиксель, у просторного — мало. Используется
    только чтобы НЕ зумить ещё сильнее то, что и так уже крупный план."""
    try:
        img = PILImage.open(photo_path).convert("L").resize((160, 90))
        arr = np.asarray(img, dtype=np.float32) if np is not None else None
        if arr is None:
            return 0.5
        gx = np.abs(np.diff(arr, axis=1)).mean()
        gy = np.abs(np.diff(arr, axis=0)).mean()
        return float(min(1.0, (gx + gy) / 40.0))
    except Exception:
        return 0.5


_FACE_CASCADE = None


_EYE_CASCADE = None   # см. _face_region_plausible() — вторичная проверка найденного "лица"


FACE_SKIN_FRAC_MIN = 0.25   # доля YCrCb-кожи в найденном "лице" — калибровано вживую (см. ниже)


FACE_EYE_MIN_SIZE_FRAC = 0.10   # мин. размер глаза относительно найденного "лица"


def _face_region_plausible(img, gray, fx, fy, fw, fh):
    """Вторая, независимая проверка НАД результатом Haar-каскада лица —
    не меняет чувствительность самого каскада (см. detect_face_anchor,
    ЧАСТЬ 13 "меч всё ещё холодный"): реальный вживую замер на 125
    уникальных стоковых кандидатах этого канала (военные предметы, доспехи,
    архивные фото) дал 39 "лиц" от голого frontalface-каскада — из них
    ПРОВЕРЕНО глазами лишь единицы настоящие (навершие меча, кинозал,
    камуфляжный геймпад и т.п. регулярно ложно триггерят каскад). Два
    независимых, бесплатных, уже-в-OpenCV сигнала, оба должны пройти:
    1) skin-tone в YCrCb (Cr/Cb-диапазон — стандартная, документированная
       эвристика детекции кожи, не выдуманная) — доля пикселей найденной
       области в человеческом диапазоне тона;
    2) вложенный eye-каскад (haarcascade_eye.xml, тот же бесплатный набор
       OpenCV) — хотя бы один глаз внутри области лица.
    Комбинация на том же тестовом наборе: 39 -> 9 кандидатов (проверено
    вживую чтением кадров — среди 9 подтверждённых лиц оказалось
    большинство настоящих, включая случай, что фильтр НЕ идеален (один
    геймпад с камуфляжной раскраской всё ещё проходит) — честно, не
    гарантия нуля ошибок, только СИЛЬНОЕ сужение частоты false positive,
    та же дисциплина, что и у _warm_mult/DOMAIN_WARM_PUSH_SCALE выше:
    только сужение сигнала, никогда не расширение (ничего, что раньше не
    считалось лицом, теперь лицом не станет)."""
    global _EYE_CASCADE
    roi_color = img[fy:fy + fh, fx:fx + fw]
    roi_gray = gray[fy:fy + fh, fx:fx + fw]
    if roi_color.size == 0 or roi_gray.size == 0:
        return False
    ycrcb = cv2.cvtColor(roi_color, cv2.COLOR_BGR2YCrCb)
    cr, cb = ycrcb[:, :, 1], ycrcb[:, :, 2]
    skin_frac = float(((cr >= 133) & (cr <= 173) & (cb >= 77) & (cb <= 127)).mean())
    if skin_frac < FACE_SKIN_FRAC_MIN:
        return False
    if _EYE_CASCADE is None:
        _EYE_CASCADE = cv2.CascadeClassifier(cv2.data.haarcascades + "haarcascade_eye.xml")
    min_eye = max(8, int(min(fw, fh) * FACE_EYE_MIN_SIZE_FRAC))
    eyes = _EYE_CASCADE.detectMultiScale(roi_gray, scaleFactor=1.1, minNeighbors=4,
                                          minSize=(min_eye, min_eye))
    return len(eyes) >= 1


def detect_face_anchor(photo_path):
    """Anchor-aware crop: раньше кроп под кадр 16:9 всегда бил ровно по
    центру исходного фото (increase+crop без смещения) — на портретных или
    непропорциональных стоковых кадрах это регулярно подрезало лицо/голову
    сверху или сбоку. Лёгкий локальный Haar-детектор (OpenCV, бесплатно,
    уже используется для параллакса — новых зависимостей и денег не стоит)
    ищет самое крупное лицо и возвращает точку привязки (fraction 0..1 по
    ширине/высоте ОРИГИНАЛА, чуть выше центра лица — глаза, не подбородок).
    Лицо не найдено/cv2 недоступен/фото не про людей (оружие, пейзаж) —
    возвращает None, и вызывающий код падает обратно на старый центр-кроп
    (то же поведение, что было всегда) — чистое дополнение без регрессии.

    Найденный каскадом регион ДОПОЛНИТЕЛЬНО проверяется _face_region_
    plausible() (skin-tone + вложенный eye-каскад) — см. её докстринг,
    реальный false-positive baг, пойманный на жалобе "меч всё ещё
    холодно выглядит"."""
    if not PARALLAX_LIBS:
        return None
    global _FACE_CASCADE
    try:
        if _FACE_CASCADE is None:
            _FACE_CASCADE = cv2.CascadeClassifier(
                cv2.data.haarcascades + "haarcascade_frontalface_default.xml")
        img = cv2.imread(photo_path)
        if img is None:
            return None
        gray = cv2.cvtColor(img, cv2.COLOR_BGR2GRAY)
        h, w = gray.shape[:2]
        min_side = int(min(w, h) * 0.08)
        faces = _FACE_CASCADE.detectMultiScale(gray, scaleFactor=1.1, minNeighbors=5,
                                                minSize=(min_side, min_side))
        if len(faces) == 0:
            return None
        fx, fy, fw, fh = max(faces, key=lambda f: f[2] * f[3])
        if not _face_region_plausible(img, gray, fx, fy, fw, fh):
            return None
        return ((fx + fw / 2) / w, (fy + fh * 0.35) / h)
    except Exception:
        return None


def spectral_saliency_anchor(photo_path, confidence_z=2.2):
    """Anchor-кроп по лицу (detect_face_anchor) покрывает ~10% кадров этого
    канала — остальное оружие/доспехи/предметы без единого лица в кадре, для
    них anchor всегда был None (центр-кроп). Saliency (spectral residual,
    Hou & Zhang 2007) — общий детектор "главного объекта" без лиц.

    Взял именно spectral residual, а не сырую плотность градиента/контраста
    (как estimate_busyness) — по конкретной причине: у сырого градиента
    текстурный ФОН (шершавый камень, кольчуга) часто даёт БОЛЬШЕ локального
    контраста, чем гладкий клинок на переднем плане — anchor утянуло бы к
    фону, кроп стал бы ХУЖЕ центрального, не лучше. Spectral residual вместо
    этого ищет то, что СТАТИСТИЧЕСКИ необычно относительно частотного
    профиля всего кадра — повторяющаяся текстура (камень, кольчуга) даёт
    низкий остаток именно потому, что она регулярна, один явный объект на
    таком фоне даёт пик. Чистый numpy (FFT) — cv2.saliency живёт только в
    opencv-contrib, которого нет в запиненном пакете (тот же класс промаха,
    что уже был с CascadeClassifier в этой сессии — не повторяем).

    ПОРОГ УВЕРЕННОСТИ (confidence_z): возвращаем anchor, только если пик
    saliency-карты заметно (z-score >= confidence_z) выше среднего уровня
    шума карты — на плоских/симметричных кадрах (широкий пейзаж, ткань)
    saliency не выражена вообще, и НАВЯЗЫВАТЬ смещение кропа туда, где нет
    реального сигнала, опаснее, чем оставить центр (см. критика раньше в
    этой же сессии). Слабый/отсутствующий пик -> None, откат на центр —
    то же safety-поведение, что и у detect_face_anchor."""
    if np is None:
        return None
    try:
        H, W = 36, 64
        img = PILImage.open(photo_path).convert("L").resize((W, H), PILImage.LANCZOS)
        gray = np.asarray(img, dtype=np.float64)
        # FFT считает кадр периодическим "по кругу" — резкий разрыв между
        # правым/левым и верхним/нижним краем сам создаёт ложную высокочастотную
        # "границу", которую spectral residual принимает за объект. Поймано
        # вживую на реальных фото канала: пик СИСТЕМАТИЧЕСКИ садился в первую
        # строку кадра (0/36) почти на каждом кадре — не совпадение, артефакт.
        # Окно Ханна плавно гасит яркость к краям перед FFT — убирает разрыв.
        win = np.outer(np.hanning(H), np.hanning(W))
        fft = np.fft.fft2(gray * win)
        amp = np.abs(fft)
        log_amp = np.log(amp + 1e-8)
        phase = np.angle(fft)
        kernel = np.ones((3, 3)) / 9.0
        avg_log_amp = _convolve2d_same(log_amp, kernel)
        residual = log_amp - avg_log_amp
        sal = np.abs(np.fft.ifft2(np.exp(residual + 1j * phase))) ** 2
        sal = _convolve2d_same(sal, np.ones((3, 3)) / 9.0)   # лёгкое сглаживание карты
        # Даже с окном Ханна самый край карты остаётся наименее надёжным —
        # исключаем внешнюю кайму из поиска пика (реальный объект в кадре
        # у стокового фотографа почти никогда не приклеен к самому краю).
        my, mx = max(1, H // 8), max(1, W // 8)
        interior = sal[my:H - my, mx:W - mx]
        if interior.size == 0:
            return None
        mean, std = float(sal.mean()), float(sal.std())
        # Верхний потолок на mean — поймано вживую: на ПОЧТИ однородном кадре
        # (плоский цвет/градиент без реальной текстуры) окно Ханна само по
        # себе создаёт плавный "холм" яркости, который residual-математика
        # принимает за огромный ложный пик (mean взлетает на 2-3 порядка
        # выше любого реального фото — проверено на 12 реальных кадрах
        # канала: 0.0005-0.00065, и на синтетическом плоском/градиентном
        # тесте: 0.33-0.74). Порог 0.02 — с большим запасом выше реальных
        # фото и с большим запасом ниже вырожденного случая.
        if std < 1e-9 or mean > 0.02:
            return None
        peak_idx = np.unravel_index(np.argmax(interior), interior.shape)
        z = (interior[peak_idx] - mean) / std
        if z < confidence_z:
            return None
        py, px = peak_idx[0] + my, peak_idx[1] + mx
        return ((px + 0.5) / W, (py + 0.5) / H)
    except Exception:
        return None


def _convolve2d_same(arr, kernel):
    """Мини-свёртка без scipy (не тянуть отдельную зависимость ради одной
    функции) — 'same'-паддинг через edge-repeat, реализация в лоб на
    маленькой (64x36) карте, скорость тут не критична."""
    kh, kw = kernel.shape
    ph, pw = kh // 2, kw // 2
    padded = np.pad(arr, ((ph, ph), (pw, pw)), mode="edge")
    out = np.zeros_like(arr)
    for i in range(kh):
        for j in range(kw):
            out += kernel[i, j] * padded[i:i + arr.shape[0], j:j + arr.shape[1]]
    return out


def resolve_crop_anchor(photo_path):
    """Единая точка входа для anchor-кропа: лицо приоритетнее (выше точность,
    когда сработало), saliency — общий фоллбэк для кадров без лиц (оружие/
    доспехи/предметы, большинство кадров этого канала). Ни один сигнал не
    найден -> None, старый центр-кроп (ноль регрессии по построению)."""
    anchor = detect_face_anchor(photo_path)
    if anchor is not None:
        return anchor
    return spectral_saliency_anchor(photo_path)


def compute_crop_offset(iw, ih, cw, ch, anchor=None):
    """increase+crop геометрия (та же, что раньше делал ffmpeg force_original_
    aspect_ratio=increase сам, без смещения) — теперь считается в Python, чтобы
    можно было подставить anchor вместо жёсткого центра. anchor=None -> тот же
    центр-кроп, что был всегда (0 изменений в дефолтном поведении)."""
    scale = max(cw / iw, ch / ih)
    nw, nh = max(cw, round(iw * scale)), max(ch, round(ih * scale))
    if anchor:
        ax, ay = anchor
        cx, cy = ax * nw, ay * nh
        x0 = int(min(max(cx - cw / 2, 0), nw - cw))
        y0 = int(min(max(cy - ch / 2, 0), nh - ch))
    else:
        x0, y0 = (nw - cw) // 2, (nh - ch) // 2
    return nw, nh, x0, y0


def choose_motion_mode(b, is_section_start, photo_hash, shot_size=None,
                       arc_stage=None):
    """Все кадры "дышат" одним и тем же классом движения (smoothstep
    zoom+pan) — фирменный почерк автослайдшоу, даже с anti-repeat на
    выборе направления. Профессиональный монтаж чередует статику, быстрый
    push-in, медленный pull-out, чистую панораму, едва заметный дрифт.
    Выбор — по ФУНКЦИИ блока в первую очередь: цифра должна читаться (не
    ехать), reveal-кадр раздела — медленный отъезд, sub-cut деталь —
    почти неподвижна (не тянет внимание с главного кадра фразы).

    shot_size (см. estimate_shot_size) — вторая, более тонкая поправка
    ПОВЕРХ выбора по функции, не вместо него: широкий план (простор,
    открытая сцена) естественнее смотрится с панорамой/медленным отъездом,
    крупный/деталь — с едва заметным дрифтом или статикой (быстрый зум на
    и без того тесном кадре съедает сам объект). Дешёвая эвристика вместо
    отдельного классификатора "портрет/архитектура/пейзаж" — используем
    уже посчитанный сигнал, а не тянем новую модель ради категорий."""
    if b.get("stat"):
        return "static_hold"
    if is_section_start:
        return "slow_pull"
    if b["section"].startswith("HOOK"):
        return "snap_push" if (photo_hash & 2) else "classic_kb"
    if b.get("is_subcut"):
        if shot_size in ("close", "detail"):
            return "micro_drift"
        return "micro_drift" if (photo_hash & 4) else "static_hold"
    # ЯЗЫК КАМЕРЫ — драматургическая стадия выбирает ПАЛИТРУ уместных
    # режимов, хэш остаётся разводящим ВНУТРИ неё. Стоит ровно здесь и
    # ни строкой выше: всё, что над этой строкой, — места, где смысл уже
    # решает (цифра обязана читаться, деталь не тянет внимание,
    # открывашка раздела это establishing), и там менять нечего.
    #
    # Замер, ради которого это написано (эпизод 02, 142 кадра, 15.09):
    # ниже этой строки сегодня попадает 104 кадра из 142, и все 104
    # получают режим движения по ХЭШУ ИМЕНИ ФАЙЛА — 96 из них один и тот
    # же classic_kb. Драматургическая стадия при этом посчитана у 142 из
    # 142 и до камеры не доходила вообще.
    #
    # Нет стадии (эпизод без speech_plan.json), выключенный флаг,
    # неизвестное имя стадии -> палитры нет -> дальше прежние правила
    # БАЙТ-В-БАЙТ. Отдельный тест это запирает.
    if arc_stage and feature_flags.enabled("CAMERA_LANGUAGE"):
        import camera_language
        _mode = camera_language.pick_from_palette(
            camera_language.camera_palette(arc_stage, shot_size), photo_hash)
        if _mode:
            return _mode
    if shot_size == "wide":
        return "horizontal_pan" if (photo_hash & 1) else "slow_pull"
    if shot_size in ("close", "detail"):
        return "micro_drift" if (photo_hash & 1) else "static_hold"
    return "horizontal_pan" if (photo_hash % 7 == 0) else "classic_kb"


def _srt_timestamp(t):
    t = max(0.0, t)
    ms_total = int(round(t * 1000))
    h, rem = divmod(ms_total, 3600000)
    m, rem = divmod(rem, 60000)
    s, ms = divmod(rem, 1000)
    return f"{h:02d}:{m:02d}:{s:02d},{ms:03d}"


SRT_MAX_LINE_CHARS = 42   # реальный, задокументированный стандарт индустрии субтитров


                           # (Netflix/BBC-класс гайдлайнов, ~40-42 символа/строка — читаемо
                           # без движения глаз поперёк всего экрана)
SRT_MAX_LINES = 2   # тот же стандарт — больше 2 строк одновременно закрывает кадр


def _wrap_caption_text(text, max_line_chars=SRT_MAX_LINE_CHARS, max_lines=SRT_MAX_LINES):
    """Перенос ОДНОГО SRT-cue на строки по РЕАЛЬНЫМ границам слов, не более
    max_lines строк — задокументированный стандарт субтитрирования (см.
    CLAUDE.md/коммит про GSA/CU Boulder captioning guidelines): короткие
    читаемые строки, разрыв по словам, никогда посередине слова.

    Не пытается влезть в max_lines любой ценой — блок, для которого даже
    после max_lines строк остаётся текст, честно дописывает остаток В
    ПОСЛЕДНЮЮ строку (длиннее стандарта, но ничего не обрезается и не
    теряется молча) — слишком длинный для 2 строк блок сценария сам по
    себе повод пересмотреть длину блока выше по пайплайну, не что чинить
    здесь угадыванием, где резать смысл."""
    words = text.split()
    if not words:
        return text
    lines, idx = [], 0
    while idx < len(words) and len(lines) < max_lines:
        cur = words[idx]
        idx += 1
        while idx < len(words):
            candidate = f"{cur} {words[idx]}"
            if len(candidate) > max_line_chars:
                break
            cur = candidate
            idx += 1
        lines.append(cur)
    if idx < len(words):
        lines[-1] = lines[-1] + " " + " ".join(words[idx:])
    return "\n".join(lines)


# Сколько текста реально помещается в один субтитр-кадр по тому же стандарту
# (SRT_MAX_LINES строк по SRT_MAX_LINE_CHARS символов). Всё, что длиннее,
# физически не может быть показано за раз — см. _split_caption_into_cues().
SRT_MAX_CUE_CHARS = SRT_MAX_LINE_CHARS * SRT_MAX_LINES


def _split_caption_into_cues(text, max_chars=SRT_MAX_CUE_CHARS,
                             max_line_chars=SRT_MAX_LINE_CHARS,
                             max_lines=SRT_MAX_LINES):
    """Разбить текст ОДНОГО блока на несколько последовательных субтитр-cue.

    РЕАЛЬНЫЙ, ИЗМЕРЕННЫЙ дефект готового файла (не гипотеза). До этой
    функции write_subtitles() писала строго один cue на блок, а
    _wrap_caption_text() честно признавала в своём докстринге, что остаток,
    не влезший в SRT_MAX_LINES строк, дописывается В ПОСЛЕДНЮЮ строку
    ("длиннее стандарта, но ничего не теряется"). Прямой прогон по
    videos/02_ne-mechom/script.txt: 94 cue из 259 (36%) получали строку
    длиннее стандарта 42 символа, САМАЯ ДЛИННАЯ — 139 символов. На
    YouTube это не "чуть длиннее": плеер переносит такую строку сам и
    закрывает текстом треть кадра поверх картинки, ради которой весь
    остальной пайплайн и работает.

    Причина дефекта была не в переносе, а в единице нарезки: у блока после
    split_long_blocks() может быть 35+ слов и 14 секунд окна — это не один
    субтитр, это три. Показывать их одновременно нельзя, а резать было
    нечем.

    Разбивка жадная по границам слов (никогда внутри слова) с ВЫРАВНИВАНИЕМ:
    сначала считаем, сколько cue нужно минимум (n = ceil(len/max_chars)), и
    наполняем до len/n, а не до max_chars. Без выравнивания жадность даёт
    хвост вида "и всё." отдельным кадром — одинокий обрывок на экране
    читается как сбой вёрстки, ровно тот же класс претензии, из-за которого
    fallback_card.py выбирает ЗАКОНЧЕННУЮ клаузу, а не обрезанную первую.

    Текст, который и так влезает в один субтитр-кадр, возвращается ОДНИМ
    элементом — для таких блоков вывод write_subtitles() остаётся
    байт-в-байт прежним. Проверка «влезает» — не по длине в символах,
    а прогоном через сам _wrap_caption_text() (цикл ниже): 11 блоков
    того же эпизода короче max_chars и всё равно не укладывались в две
    строки, потому что ломаются по словам неудачно — ранний выход по
    длине их и пропускал.
    """
    words = (text or "").split()
    if not words:
        return [text or ""]

    def _fits(chunk):
        wrapped = _wrap_caption_text(chunk).split("\n")
        return len(wrapped) <= max_lines and all(len(l) <= max_line_chars for l in wrapped)

    def _fill(limit_chars):
        """Жадно набирает cue, пока следующий шаг не ломает стандарт.
        limit_chars — мягкая цель по длине (для балансировки); жёсткое
        условие всегда одно и то же — _fits(), то есть РЕАЛЬНЫЙ перенос."""
        out, cur = [], ""
        for w in words:
            cand = f"{cur} {w}".strip()
            if cur and (len(cand) > limit_chars or not _fits(cand)):
                out.append(cur)
                cur = w
            else:
                cur = cand
        if cur:
            out.append(cur)
        return out

    # Шаг 1 — максимально плотная набивка: даёт МИНИМАЛЬНО возможное число
    # cue. Минимальное здесь важно не из экономии: каждый лишний cue режет
    # окно блока на более короткие куски, а cue короче ~0.7с читается как
    # мигание, а не как субтитр (реальный регресс первой версии этой
    # функции — она дробила на n частей "по формуле" и на 259 блоках
    # эпизода 02 дала 44 cue короче 0.7с, которых до неё не было ни одного).
    packed = _fill(max_chars)
    # Шаг 2 — балансировка на ТО ЖЕ число cue: жадная набивка оставляет
    # хвост вида "и всё." отдельным кадром, а одинокий обрывок на экране
    # читается как сбой вёрстки (тот же класс претензии, из-за которого
    # fallback_card.py берёт ЗАКОНЧЕННУЮ клаузу, а не обрезанную первую).
    # Берём балансировку ТОЛЬКО если она не увеличила число cue и каждый
    # кусок по-прежнему проходит _fits(); иначе остаётся плотный вариант.
    if len(packed) > 1:
        total = len(" ".join(words))
        # Перебор мягкой цели от самой ровной (total/n) до плотной
        # (max_chars): первая, что укладывается в то же число cue и
        # проходит _fits() — самая ровная из возможных. Одной попытки
        # (ровно total/n) не хватает: на неудачной границе слова она
        # ломается, и код откатывался на плотный вариант с хвостом в 4
        # символа — 14 таких сирот на эпизоде 02. Перебор конечен и
        # заведомо результативен: на limit == max_chars он вырождается
        # ровно в packed.
        for limit in range(math.ceil(total / len(packed)), max_chars + 1):
            balanced = _fill(limit)
            if len(balanced) <= len(packed) and all(_fits(c) for c in balanced):
                return balanced
    return packed


def write_subtitles(video_dir, blocks, starts, durs, real_weights=None):
    """SRT — бесплатный побочный продукт уже посчитанного тайминга: реальный
    посимвольный alignment.csv (см. load_alignment_weights) уже участвует в
    расчёте durs/starts, отдельно парсить CSV второй раз не нужно. starts —
    РЕАЛЬНОЕ аудио-время (block_durations по total, не по раздутой под xfade
    target — та же модель, что уже использует energy_pace_multipliers для
    сэмплинга кривой громкости, см. main()), иначе субтитры разъехались бы
    с озвучкой на сумму xfade-нахлёстов к концу ролика.

    Один блок = один субтитр-кадр: текст уже чистый (теги вырезаны в
    parse_blocks), деления и так на границах пауз/фраз — не нужно заново
    резать по 5-7 слов, разбивка уже смысловая.

    Видимое окно субтитра НЕ включает хвостовую паузу блока (2.7, тот же
    класс бага, что уже чинили в load_hook_word_timings): durs[i] —
    ПОЛНОЕ окно блока, block_durations() прибавляет b["pause_after"] к весу
    ДО floor/cap/глобального scale, так что субтитр держался бы на экране
    почти всю следующую паузу — визуально текст "отстаёт" от голоса на
    тишине. real_weights (если есть) даёт долю паузы в исходном сыром весе
    блока — она инвариантна к равномерному масштабированию, обрезаем ею
    durs[i] перед показом. Без real_weights (старый вызов/фоллбэк) — как
    раньше, полное окно."""
    path = os.path.join(video_dir, "subtitles.srt")
    lines = []
    n = 0
    for i, (b, s, d) in enumerate(zip(blocks, starts, durs)):
        text = b["text"].strip()
        if not text:
            continue
        pause_after = b.get("pause_after") or 0.0
        w = real_weights[i] if (real_weights and i < len(real_weights) and real_weights[i]) else None
        visible_d = d * (1.0 - pause_after / (w + pause_after)) if (pause_after > 0 and w) else d
        # Блок длиннее одного субтитр-кадра показывается НЕСКОЛЬКИМИ cue
        # подряд (см. _split_caption_into_cues): окно блока делится между
        # ними ПРОПОРЦИОНАЛЬНО числу символов. Это оценка внутри блока, но
        # строго более точная, чем то, что было: раньше весь текст блока
        # висел на экране целиком всё его окно, то есть последняя фраза
        # блока показывалась с самого начала — за секунды до того, как её
        # произнесут. Границы cue вычисляются нарастающим итогом от одного
        # и того же старта, чтобы они плотно покрыли окно без щелей и
        # нахлёстов (та же дисциплина "квантуем границы, а не длительности",
        # что и в phrase_locked_durations).
        cues = _split_caption_into_cues(text)
        chars_total = sum(len(c) for c in cues) or 1
        acc_chars = 0
        for c in cues:
            cue_start = s + visible_d * (acc_chars / chars_total)
            acc_chars += len(c)
            cue_end = s + visible_d * (acc_chars / chars_total)
            n += 1
            lines.append(str(n))
            lines.append(f"{_srt_timestamp(cue_start)} --> "
                         f"{_srt_timestamp(max(cue_end, cue_start + 0.3))}")
            lines.append(_wrap_caption_text(c))
            lines.append("")
    open(path, "w", encoding="utf-8").write("\n".join(lines))
    return path


WOBBLE_AMP_CANVAS_PX = 6.0   # ~1.4px в итоговом 1920-кадре (канва 8000px) — см. kenburns()


FREEZE_HOLD_DUR = 0.35       # секунд остановки движения перед stat-плашкой — см. kenburns()


# Адаптивный холст для kenburns() (по умолчанию ВЫКЛЮЧЕН — байт-в-байт
# старое поведение с фиксированными 8000x4500). Реальный, измеренный вживую
# (01_ves-mecha, ночь 31 авг/1 сен) остаток времени клипа, не объяснённый
# ни одной ML-моделью — zoompan однопоточен, его стоимость на кадр растёт
# вместе с разрешением холста, а 8000x4500 (36 Мп) апскейлит ЛЮБОЕ фото
# (реальные Pexels large2x — ~1880px по длинной стороне, проверено ffprobe
# на 54 закэшированных файлах эпизода) в 4+ раза больше, чем нужно.
# KENBURNS_CANVAS_MARGIN выведен из уже существующих в kenburns() констант
# зума (не с потолка): максимально возможный zoom = ZOOM_FLOOR (1.04) +
# ZOOM_DELTA_MAX (0.22) = 1.26 — то есть холст шириной WIDTH*1.26 уже
# достаточен, чтобы на пике зума кроп-окно (canvas/zoom) не апскейлилось
# при финальном ресайзе в WIDTHxHEIGHT. 1.5 — тот же запас, что уже
# ПРОВЕРЕН В ПРОДЕ на самых заметных кадрах ролика (хук/climax/начало
# разделов) — см. PARALLAX_MARGIN/fill_crop_canvas() ниже, тот же принцип,
# независимо выведенное число оказалось близко (1.26 нужно, 1.5 даёт
# честный запас на панораму/округление/anchor-кроп).
KENBURNS_ADAPTIVE_CANVAS = os.environ.get("KENBURNS_ADAPTIVE_CANVAS", "0") != "0"


KENBURNS_CANVAS_MARGIN = 1.5


def _kenburns_canvas_size():
    """(ширина, высота) рабочего холста kenburns() ДО crop/zoompan. Вынесена
    отдельной чистой функцией ради юнит-теста — сама по себе ни на что не
    влияет, флаг читается в момент вызова (не на импорте), см. тесты
    monkeypatch KENBURNS_ADAPTIVE_CANVAS."""
    if not KENBURNS_ADAPTIVE_CANVAS:
        return 8000, 4500
    return round(WIDTH * KENBURNS_CANVAS_MARGIN), round(HEIGHT * KENBURNS_CANVAS_MARGIN)


def piecewise_ease_expr(t_expr, points):
    """Составная (multi-phase) траектория вместо одной гладкой кривой на
    весь клип — "push → micro-pan → settle" или "pull → reveal → hold".
    points — контрольные точки [(0.0,0.0), ..., (1.0,1.0)] по возрастанию t.

    Аудит 04.09 (измерено SIFT-масштабом на реальных клипах ep_base): прежняя
    реализация — НЕЗАВИСИМЫЙ smoothstep на каждом сегменте — имеет нулевую
    производную на ОБОИХ концах каждого сегмента, поэтому в каждом внутреннем
    узле (classic_kb: t=0.5 и 0.85; slow_pull: 0.55 и 0.85) движение камеры
    физически останавливалось: скорость зума 5.4‰/3 кадра → 0.4‰ (×13
    медленнее) → снова разгон. Это ровно «остановка раньше времени», которую
    ЧАСТЬ 6 CLAUDE.md запрещает, на КАЖДОМ фото-клипе.

    Теперь — монотонный кубический сплайн Эрмита (наклоны в узлах по
    Fritsch–Butland: гармоническое среднее секущих, монотонность
    гарантирована, перелёта нет). Нулевой наклон — только на глобальных
    концах (плавный старт и стоп, как у smoothstep); во внутренних узлах
    скорость непрерывна и НЕ нулевая. Для двух точек [(0,0),(1,1)]
    вырождается ровно в прежний smoothstep 3t²-2t³. Возвращает строку
    ffmpeg-eval выражения, t_expr — переменная времени 0..1 (обычно on/frames)."""
    n = len(points)
    if n < 2:
        return f"{points[-1][1]:.4f}"
    ts = [float(p[0]) for p in points]
    vs = [float(p[1]) for p in points]
    h = [ts[i + 1] - ts[i] for i in range(n - 1)]
    delta = [(vs[i + 1] - vs[i]) / h[i] if h[i] > 0 else 0.0 for i in range(n - 1)]
    m = [0.0] * n
    for i in range(1, n - 1):
        if delta[i - 1] * delta[i] <= 0:
            m[i] = 0.0
        else:
            w1 = 2 * h[i] + h[i - 1]
            w2 = h[i] + 2 * h[i - 1]
            m[i] = (w1 + w2) / (w1 / delta[i - 1] + w2 / delta[i])
    expr = f"{vs[-1]:.4f}"
    for i in range(n - 1, 0, -1):
        t0, v0, t1, v1 = ts[i - 1], vs[i - 1], ts[i], vs[i]
        u = f"(({t_expr}-{t0:.4f})/{h[i - 1]:.4f})"
        # Базис Эрмита: h00*v0 + h10*h*m0 + h01*v1 + h11*h*m1
        seg = (f"({v0:.4f}*(2*pow({u},3)-3*pow({u},2)+1)"
               f"+{h[i - 1] * m[i - 1]:.5f}*(pow({u},3)-2*pow({u},2)+{u})"
               f"+{v1:.4f}*(3*pow({u},2)-2*pow({u},3))"
               f"+{h[i - 1] * m[i]:.5f}*(pow({u},3)-pow({u},2)))")
        expr = f"if(lt({t_expr}\\,{t1:.4f})\\,{seg}\\,{expr})"
    return expr


def render_tmp_path(out):
    """Промежуточный путь для АТОМАРНОЙ записи клипа — рендерим сюда, потом
    os.replace() в финальный `out` ТОЛЬКО при успехе (см. finalize_render()).
    Без этого убитый процесс (SIGKILL/OOM/обрыв контейнера — ровно так один
    раз уже падал многочасовой фоновый рендер без единой строчки трейсбека)
    посреди записи оставляет ОБРЕЗАННЫЙ mp4 ровно по пути, который кэш
    main() (простая проверка os.path.exists(out)) на следующем запуске
    молча считает валидным готовым клипом — порченый кадр всплыл бы только
    на сборке/просмотре готового ролика, не в момент самого рендера."""
    return out + ".partial.mp4"


def finalize_render(tmp, out, ok):
    """Переименовать tmp -> out атомарно при успехе; подчистить огрызок при
    провале — см. render_tmp_path(). os.replace — атомарная операция на
    одной файловой системе (tmp и out всегда в одной папке), не "скопировать
    и удалить" — на успешном пути либо всего файла целиком не существует,
    либо он полностью готов, никакого промежуточного полу-состояния."""
    if ok and os.path.exists(tmp):
        os.replace(tmp, out)
        return True
    if os.path.exists(tmp):
        try:
            os.remove(tmp)
        except OSError:
            pass
    return False


# --- Отказоустойчивый рендер клипа: код возврата ffmpeg сам по себе НЕ
# гарантирует, что записанный файл реально того же качества/длины, что
# заказано (редкий, но реальный класс сбоя — процесс отчитался успехом на
# усечённом/битом выводе). verify_clip() — независимая от кода возврата
# проверка через ffprobe; run_ffmpeg_with_retry() — несколько попыток одной
# и той же команды с верификацией после каждой, транзиентный сбой (диск,
# память, гонка) часто не повторяется на следующей попытке.
CLIP_VERIFY_TOLERANCE_SEC = 0.25   # допуск между заказанной и фактической длительностью клипа


RENDER_RETRY_ATTEMPTS = max(1, int(os.environ.get("RENDER_RETRY_ATTEMPTS", "3")))


RENDER_RETRY_BACKOFF_SEC = 1.5


def render_timeout_sec(dur):
    """Таймаут на ОДНУ попытку рендера клипа длительностью dur секунд.
    РЕАЛЬНЫЙ, пойманный вживую при разработке этого модуля случай: ffmpeg
    `-loop 1 -i <битый/усечённый файл>` не падает с ошибкой декода — он
    ВИСНЕТ БЕСКОНЕЧНО (проверено напрямую: процесс пришлось убивать по
    внешнему timeout, ни строчки вывода за 10+ секунд). Без явного таймаута
    ретрай вообще не срабатывает — первая же попытка никогда не возвращает
    управление, чтобы её можно было повторить.
    Плоский пол 30с ("15x реального времени клипа") оказался НЕВЕРНЫМ на
    практике: под реальной нагрузкой пула воркеров (RENDER_POOL_WORKERS,
    несколько ffmpeg с тяжёлым filter_complex — scale до 8000x4500, gblur,
    deband, unsharp — одновременно; -threads 1 ограничивает только
    энкодер, НЕ фильтр-граф — filter_complex_threads отдельный флаг, тоже
    не выставлен) короткие (~1-2с) под-катные клипы ловили ложный таймаут
    под реальным контеншном. Плоский подъём пола (проверено: 180с) чинил
    это, но ломал другую сторону — тест на реальное бесконечное
    зависание (битый файл, RENDER_PARALLEL=0, один воркер, contention=1)
    честно ждал все 180с на одну заведомо безнадёжную попытку вместо
    прежних быстрых 30с. Обе цифры были правильными каждая для своего
    сценария — но врозь, не как одна константа. Правильный сигнал уже
    существует в коде: RENDER_POOL_ENABLED/RENDER_POOL_WORKERS. Пол
    масштabируется контеншном пула, а не берётся с потолка одним числом
    для всех режимов: при выключенном пуле (RENDER_PARALLEL=0, как в
    последовательном рендере) contention=1 -> те же 30с, что и были
    (не трогаем то, что уже подтверждено рабочим); при N воркерах в
    пуле — 30с*N, тот же принцип, которым уже руководствуется
    _default_render_workers() (нагрузка растёт вместе с числом
    параллельных ffmpeg). Проверено вживую на 4-ядерной машине с
    RENDER_POOL_WORKERS=3 (90с пол) — реальный прогон 4 клипов проходит
    с первой попытки на каждый клип, суммарно на весь пул 73.8с.

    РЕАЛЬНЫЙ пойманный вживую пробел (не гипотеза): формула выше учитывает
    ТОЛЬКО contention от RENDER_POOL_WORKERS — но parallax_kenburns()
    (2.5D-параллакс на highlight-кадрах, см. is_parallax_highlight())
    всегда выполняется ПОСЛЕДОВАТЕЛЬНО в главном процессе, а не в пуле, и
    сам по себе тяжёлый ffmpeg-энкод (тот же дорогой film_look() с
    gblur=14 bloom-эффектом, что и у остальных клипов). Пока он идёт,
    реальное число одновременных тяжёлых ffmpeg-процессов на машине —
    RENDER_POOL_WORKERS ИЗ ПУЛА плюс ЕЩЁ ОДИН в главном процессе, а
    формула этого не считала. На 4-ядерной песочнице поймано вживую:
    изолированный (без конкуренции) прогон тяжёлого клипа — 112-224с,
    под реальной нагрузкой пула — таймаут на ровно той же цифре, что
    выдавала формула (contention=3 -> ~418-429с), 3 попытки подряд.
    +1 к contention — честный запас именно под эту, ранее не посчитанную
    добавку от параллакса, не гадание с потолка."""
    contention = (RENDER_POOL_WORKERS + 1) if RENDER_POOL_ENABLED else 1
    return max(30 * contention, dur * 15 * contention)


def verify_clip(path, expected_dur, tolerance=CLIP_VERIFY_TOLERANCE_SEC):
    """ffprobe-верификация уже отрендеренного клипа — единственный источник
    правды о том, что реально записано на диск, независимый от кода
    возврата ffmpeg. Возвращает (ok, reason, actual_dur|None)."""
    try:
        r = subprocess.run(["ffprobe", "-v", "quiet", "-print_format", "json",
                            "-show_format", "-show_streams", path],
                           capture_output=True, text=True, encoding="utf-8", errors="replace", timeout=20)
        if r.returncode != 0:
            return False, "ffprobe не смог прочитать файл", None
        data = json.loads(r.stdout)
        if not any(s.get("codec_type") == "video" for s in data.get("streams", [])):
            return False, "в файле нет видеопотока", None
        actual_dur = float(data["format"]["duration"])
        if actual_dur < max(0.1, expected_dur - tolerance):
            return False, f"длительность {actual_dur:.2f}с короче заказанной {expected_dur:.2f}с", actual_dur
        return True, "ok", actual_dur
    except Exception as e:
        return False, f"{type(e).__name__}: {e}", None


def _looks_like_drawtext_failure(reason):
    """True — ТОЛЬКО если reason (см. run_ffmpeg_with_retry) реально
    указывает на недоступность drawtext/шрифта (некоторые сборки ffmpeg
    собраны без libfreetype/drawtext вообще — единственный случай, ради
    которого существует откат "рисую без них" у kenburns()/video_render()).

    РЕАЛЬНЫЙ БАГ, найден по жалобе пользователя ("субтитров нет вначале,
    потом резко появляются, рассинхрон") на реальном рендере: откат раньше
    срабатывал на ЛЮБОЙ reason, включая таймаут/OOM/гонку ресурсов —
    транзиентный сбой (в конкретном случае: CPU-контеншн от параллельного
    процесса) ронял ВСЕ попытки WITH-captions рендера по таймауту, код
    трактовал это как "drawtext не работает" и молча перерисовывал клип БЕЗ
    подписей — та версия проще/быстрее и укладывалась в лимит времени, где
    сложная (с подписями) не успевала. Итог на экране: подписи есть не на
    всех клипах хука, без единой строчки в логе, объясняющей почему именно
    эти. Теперь откат без подписей — только когда причина реально об этом
    (drawtext/шрифт), любой другой сбой после исчерпанных попыток — честный
    провал ВСЕГО клипа (тот же путь, что systematic ffmpeg-ошибка), не тихая
    потеря подписей."""
    r = (reason or "").lower()
    return any(sig in r for sig in
               ("drawtext", "fontfile", "font file", "no such filter", "unrecognized option",
                "unable to parse option value", "cannot load default config"))


def run_ffmpeg_with_retry(build_cmd, tmp_out, expected_dur, label=""):
    """Прогоняет build_cmd() (callable без аргументов — каждый вызов строит
    и исполняет НОВУЮ ffmpeg-команду в tmp_out, возвращает CompletedProcess)
    до RENDER_RETRY_ATTEMPTS раз. После КАЖДОГО ненулевого-кода-возврата
    успеха дополнительно проверяет реальный файл через verify_clip() —
    returncode==0 сам по себе недостаточен (см. комментарий у
    CLIP_VERIFY_TOLERANCE_SEC). Систематический сбой (битый вход, кодек)
    повторится тем же образом на всех попытках и честно вернёт (False,
    причина); транзиентный (гонка, нехватка ресурсов в моменте) часто
    лечится самим повтором. Возвращает (ok, reason)."""
    last_reason = "неизвестная ошибка"
    for attempt in range(1, RENDER_RETRY_ATTEMPTS + 1):
        if os.path.exists(tmp_out):
            try:
                os.remove(tmp_out)
            except OSError:
                pass
        try:
            r = build_cmd()
        except subprocess.TimeoutExpired:
            # РЕАЛЬНЫЙ случай, пойманный при разработке (см. render_timeout_sec):
            # ffmpeg на битом/усечённом входе не падает с ошибкой декода —
            # виснет БЕСКОНЕЧНО. Без этого перехвата TimeoutExpired улетел бы
            # наружу и уронил бы весь рендер (или воркер пула), а не дал
            # честное "не получилось, пробуем ещё раз/сдаёмся".
            last_reason = f"таймаут ({render_timeout_sec(expected_dur):.0f}с) — процесс завис"
            r = None
        except Exception as e:
            last_reason = f"{type(e).__name__}: {e}"
            r = None
        if r is None:
            pass   # уже записали last_reason выше
        elif r.returncode != 0:
            stderr_tail = (r.stderr or "")[-200:] if hasattr(r, "stderr") else ""
            last_reason = f"ffmpeg вышел с кодом {r.returncode}: {stderr_tail}"
        else:
            ok, reason, _ = verify_clip(tmp_out, expected_dur)
            if ok:
                if attempt > 1:
                    print(f"  [{label}] ok с {attempt}-й попытки")
                return True, "ok"
            last_reason = reason
        if attempt < RENDER_RETRY_ATTEMPTS:
            print(f"  [{label}] попытка {attempt}/{RENDER_RETRY_ATTEMPTS} не удалась ({last_reason}), повтор...")
            time.sleep(RENDER_RETRY_BACKOFF_SEC)
    return False, last_reason


def kenburns(photo, out, dur, title=None, zoom_in=None, pan_dir=None, stat=None,
             section="", motion_mode="classic_kb", stat_variant=0,
             brightness_bias=0.0, energy_bias=0.0, stat_delay=0.0, levels=None, wb=None,
             grain_scale=1.0, captions=None, look_filter=None, ffmpeg_threads=None, domain=None):
    # Портретный источник вписывается целиком на размытую подложку ДО всего
    # остального (см. aspect_fit_backdrop): дальше по цепочке он уже 16:9, и
    # ни anchor-кроп, ни zoompan, ни грейд не знают про этот шаг вообще.
    # Кадр 4:3 и шире возвращается тем же путём — ноль изменений.
    # До подложки — вырезка вокруг смысловой детали (focus_crop): страница
    # рукописи становится сценой на ней. Нет рамки — тот же путь.
    photo = focus_crop(photo)
    photo = aspect_fit_backdrop(photo)
    frames = max(1, round(dur * FPS))
    # KENBURNS_ADAPTIVE_CANVAS=0 (дефолт) -> ровно 8000x4500, как раньше,
    # байт-в-байт. См. докстринг константы у объявления выше.
    kb_cw, kb_ch = _kenburns_canvas_size()
    h, zoom_in_default, pan_dir_default = kb_hash_choices(photo)
    if zoom_in is None:
        zoom_in = zoom_in_default
    dx, dy = pan_dir if pan_dir is not None else pan_dir_default
    rate_jit = ((h >> 5) % 1000) / 1000.0
    pan_jit = ((h >> 15) % 1000) / 1000.0
    # C6: скорость зума в такт энергии голоса — на эмоциональных пиках речи
    # камера "подбирается" быстрее, на спокойных местах медленнее, тот же
    # energy_bias, что уже модулирует контраст/сатурацию в film_look().
    # Клэмп ZOOM_DELTA_MIN/MAX всё равно применяется ПОСЛЕ — энергия сдвигает
    # в пределах уже безопасного диапазона, не расширяет его.
    energy_zoom_mult = 1.0 + max(-0.5, min(0.5, energy_bias)) * 0.2
    delta = max(ZOOM_DELTA_MIN, min(ZOOM_DELTA_MAX,
                ZOOM_RATE_BASE * dur * (0.75 + rate_jit * 0.5) * energy_zoom_mult))
    # Уже тесный/плотный кадр (крупный план) не нуждается в таком же зуме,
    # как просторный — иначе на кадре и так крупного меча к концу клипа
    # остаётся одна текстура металла, некуда уже приближаться со смыслом.
    busy = estimate_busyness(photo)
    if busy > 0.6:
        delta *= 0.7
    # PAN_SAFETY * jitter всегда < 1.0 (проверено численно) — офсет остаётся
    # строго внутри геометрического запаса (1-1/zoom)/2 на любом кадре клипа.
    pan_amt = PAN_SAFETY * (PAN_JITTER_MIN + pan_jit * (PAN_JITTER_MAX - PAN_JITTER_MIN))
    on_expr = "on"
    # Freeze-hold: короткая остановка движения ПРЯМО ПЕРЕД тем, как
    # появляется stat-плашка (stat_delay — см. main()/add_overlays,
    # тот же момент, синхронизированный с реальной озвучкой числа).
    # Контраст "движение → пауза → цифра" — приём, отличающий монтаж
    # с намерением от бесшовной анимации без акцентов. Замораживаем
    # именно ПЕРЕМЕННУЮ ВРЕМЕНИ (виртуальный "on"), а не сами zoom/pan —
    # эффект автоматически подхватывается ЛЮБЫМ motion_mode без
    # дублирования логики в каждой ветке. Движение после паузы продолжает
    # с того же места, откуда остановилось (не теряет фазу), а не рестартует.
    if stat and stat_delay > 0.5:
        # ТОТ ЖЕ кламп, что у add_overlays, и через ту же константу — два
        # литерала 1.2 уже жили здесь порознь, а расхождение значило бы, что
        # «пауза перед цифрой» и сама цифра случаются в разные моменты.
        # Аудит 04.09: при [stat:] в конце фразы плашка появлялась на
        # dur-резерв, а пауза по сырому stat_delay случалась ПОСЛЕ неё.
        eff_delay = max(0.0, min(stat_delay, dur - STAT_PLATE_TAIL_SEC))
        freeze_start_f = max(0, round((eff_delay - FREEZE_HOLD_DUR) * FPS))
        freeze_end_f = round(eff_delay * FPS)
        if freeze_end_f > freeze_start_f:
            on_expr = (f"if(lt(on\\,{freeze_start_f})\\,on\\,"
                       f"if(lt(on\\,{freeze_end_f})\\,{freeze_start_f}\\,"
                       f"on-{freeze_end_f - freeze_start_f}))")
    t = f"({on_expr}/{frames})"
    # smoothstep вместо линейного роста: старт/финиш без рывка — линейный зум
    # это самый узнаваемый штамп шаблонных слайд-шоу.
    eased = f"(3*pow({t},2)-2*pow({t},3))"

    if motion_mode == "static_hold":
        # Цифра должна читаться — кадр не едет вообще. Лёгкий "дышащий" зум
        # (не 1.0 буквально — совсем мёртвый стоп-кадр сам по себе штамп)
        # без пана.
        delta = min(delta, 0.02)
        pan_amt = 0.0
    elif motion_mode == "classic_kb":
        # Multi-phase вместо одной ровной кривой на весь клип: "push →
        # micro-pan → settle" — быстрый ход в первой половине, спокойное
        # продолжение, гладкая остановка перед резом. Одна гладкая кривая
        # от начала до конца — сама по себе узнаваемый штамп "программа
        # анимировала", реальная камера редко держит идеально постоянную
        # скорость до самого конца движения.
        eased = piecewise_ease_expr(t, [(0.0, 0.0), (0.5, 0.72), (0.85, 0.95), (1.0, 1.0)])
    elif motion_mode == "snap_push":
        # Быстрый punch-in за ~0.3с, дальше — hold на максимуме. eased
        # клампится к 1.0 рано (по доле кадров, не по общей длительности —
        # короткий hook-кадр и так короткий).
        snap_frac = min(0.95, max(0.05, 8 / frames))
        eased = f"min(1,{t}/{snap_frac})"
        eased = f"(3*pow({eased},2)-2*pow({eased},3))"
        zoom_in = True
        delta = max(delta, ZOOM_DELTA_MIN * 1.4)
        pan_amt *= 0.4   # пан почти не нужен — внимание на резкость punch-in
    elif motion_mode == "slow_pull":
        # Reveal кадр раздела: стартуем зумленными, спокойно отъезжаем.
        # Без пана — это медленный отъезд, а не комбинация приёмов.
        # Multi-phase: "pull → reveal → hold" — основной отъезд в первой
        # половине-двух третях клипа, дальше движение гасится к спокойному
        # hold перед резом (реальный оператор не продолжает тянуть камеру
        # рывками ровно до конца кадра).
        zoom_in = False
        delta = max(delta, ZOOM_DELTA_MIN * 1.6)
        pan_amt = 0.0
        eased = piecewise_ease_expr(t, [(0.0, 0.0), (0.55, 0.68), (0.85, 0.92), (1.0, 1.0)])
    elif motion_mode == "horizontal_pan":
        # Почти чистая панорама — для длинных объектов (клинки, карты,
        # гравюры). ВАЖНО: offset пана ниже завязан на (1-1/zoom) — растёт
        # ВМЕСТЕ с изменением зума, а не по отдельной шкале времени. При
        # delta=0 (зум строго константа) этот множитель тоже был бы
        # константой — пан физически не двигался бы кадр от кадра (поймано
        # при проверке формулы, не вживую). Держим delta малой, но не
        # нулевой — зум еле заметен, а пан (усиленный) реально едет.
        delta = min(delta, 0.06)
        pan_amt = PAN_SAFETY * 0.95
        # Аудит 04.09: pan_dir выбирался независимо от режима — у 25% таких
        # клипов dx=0 (панорама без горизонтального движения), у половины —
        # диагональ. Режим обязан задавать направление сам, как snap_push
        # задаёт zoom_in.
        dx, dy = (dx if dx else (1 if (h >> 9) & 1 else -1)), 0
    elif motion_mode == "micro_drift":
        # Едва заметное движение — не тянет внимание с главного кадра
        # sub-cut-фразы.
        delta = min(delta, 0.03)
        pan_amt = 0.0
    max_zoom = ZOOM_FLOOR + delta
    z = (f"'{ZOOM_FLOOR}+{delta:.5f}*{eased}'" if zoom_in
         else f"'{max_zoom:.5f}-{delta:.5f}*{eased}'")
    # Film weave: математически идеальная smoothstep-кривая зума/пана — сама
    # по себе штамп "отрендерено алгоритмом", у настоящей камеры/плёнки
    # всегда есть микро-дрожь. Низкочастотный синус (не шум per-frame — это
    # выглядело бы как тряска, не имитация плёнки), амплитуда и фаза/период —
    # детерминированно по хэшу фото. Меньше цикла за весь клип (0.6-1.4) —
    # чтобы не читалось как заметное "покачивание туда-сюда".
    # Абсолютное значение в пикселях калибровано под холст 8000px (см.
    # докстринг константы) — масштабируем пропорционально РЕАЛЬНОМУ холсту
    # (kb_cw), иначе при меньшем холсте то же число пикселей — заметно
    # более сильное "дрожание плёнки" относительно кадра. При выключенном
    # KENBURNS_ADAPTIVE_CANVAS kb_cw==8000 -> множитель==1.0, ноль изменений.
    wob_amp = (WOBBLE_AMP_CANVAS_PX * (kb_cw / 8000.0)) * (0.5 if motion_mode == "static_hold" else 1.0)
    wob_px = f"{wob_amp:.2f}*sin(2*PI*(on/{frames})*{0.6 + ((h >> 19) % 100) / 125.0:.3f}+{((h >> 3) % 628) / 100.0:.3f})"
    wob_py = f"{wob_amp:.2f}*sin(2*PI*(on/{frames})*{0.6 + ((h >> 23) % 100) / 125.0:.3f}+{((h >> 11) % 628) / 100.0:.3f})"
    # margin = (1-1/zoom)/2 считается от РЕАЛЬНОГО zoom в текущем кадре (переменная
    # zoompan даёт его сама) — офсет безопасен на любом кадре клипа по построению,
    # а не только к концу движения, как раньше при завязке на delta.
    x = (f"'iw/2-(iw/zoom/2){dx * pan_amt:+.5f}*(1-1/zoom)/2*iw+{wob_px}'" if dx
         else f"'iw/2-(iw/zoom/2)+{wob_px}'")
    y = (f"'ih/2-(ih/zoom/2){dy * pan_amt:+.5f}*(1-1/zoom)/2*ih+{wob_py}'" if dy
         else f"'ih/2-(ih/zoom/2)+{wob_py}'")
    # increase+crop (не decrease+pad) — исходные фото редко ровно 16:9, "вписать
    # в рамку" оставляло чёрные поля по краям на большинстве кадров (проверено:
    # 3 из 8 тестовых кадров с полосами по обеим сторонам). Залить кадр целиком
    # и обрезать лишнее — тот же приём, что уже применялся к видео-стоку ниже.
    # Anchor-aware: кроп бьёт по центру, только если ни лицо, ни saliency
    # не нашли уверенного сигнала (см. resolve_crop_anchor) — иначе
    # смещается так, чтобы не резать голову/главный объект.
    try:
        iw, ih = image_size_as_rendered(photo)
    except Exception:
        iw, ih = kb_cw, kb_ch
    anchor = resolve_crop_anchor(photo)
    nw, nh, cx0, cy0 = compute_crop_offset(iw, ih, kb_cw, kb_ch, anchor)
    vf_base = (f"scale={nw}:{nh},"
               f"crop={kb_cw}:{kb_ch}:{cx0}:{cy0},setsar=1,"
               f"zoompan=z={z}:x={x}:y={y}:"
               f"d={frames}:s={WIDTH}x{HEIGHT}:fps={FPS},"
               f"{film_look(h, section, brightness_bias, energy_bias, levels, wb, domain)}"
               # Reference-Guided Look Management (см. scripts/look_reference.py) —
               # ДОБАВОЧНЫЙ фрагмент ПОСЛЕ уже готового film_look(), никогда не
               # заменяет его. look_filter=None (фича выключена/lookbook пуст/
               # низкая уверенность/лицо в кадре и т.д.) -> без изменений.
               + (f",{look_filter}" if look_filter else ""))
    vf_overlay = None
    if title or stat or captions:
        vf_overlay = add_overlays(vf_base, dur, title, stat, stat_variant, stat_delay, media_path=photo)
        vf_overlay = add_kinetic_captions(vf_overlay, captions)

    tmp_out = render_tmp_path(out)

    def render(vf):
        # -framerate 1 на зациклённом фото: без него image2-демуксер отдаёт
        # 25 кадров/с, и КАЖДЫЙ из них проходит scale=8000x4500 (36 Мпикс
        # апскейл), хотя zoompan берёт ОДИН входной кадр и сам делает из
        # него все d=frames выходных. Замер 03.09 на клипе 80 кадров:
        # 6.0с -> 4.6с на стадии zoompan+кодирование, выход побайтово
        # идентичен (80 кадров, нулевая разница по пикселям на первом/
        # среднем/последнем кадре).
        cmd = ["ffmpeg", "-y", "-framerate", "1", "-loop", "1", "-i", photo]
        if GRAIN_ENABLED:
            # Зерно — отдельный вход (зацикленный grain_loop.mp4), не строка
            # фильтров — filter_complex вместо -vf, тот же приём, что уже
            # используется для speed ramp/halation embedding.
            cmd += ["-stream_loop", "-1", "-i", GRAIN_LOOP_PATH]
            fc = f"[0:v]{vf}[gr_in];{grain_blend_complex('gr_in', 1, 'vout', grain_scale)}"
            cmd += ["-filter_complex", fc, "-map", "[vout]"]
        else:
            cmd += ["-vf", vf]
        # -frames:v, а НЕ -t: заказ в кадрах — единственная точная единица
        # (столько же кадров, сколько заложено в zoompan d=frames и в
        # тайминг склейки). С -t граница "последний кадр влез/не влез"
        # решалась сравнением дробных секунд, и клип регулярно выходил на
        # один кадр длиннее заказанного — на сотнях клипов эпизода это
        # складывалось в секунды ухода видео от голоса (см.
        # quantize_durations_to_frames). Так же уже работает
        # parallax_kenburns(), путь просто приведён к одному виду.
        cmd += ["-frames:v", str(frames), "-c:v", "libx264", "-preset", RENDER_PRESET,
               "-crf", RENDER_CRF, "-r", str(FPS)] + CLIP_PIX_ARGS + COLOR_META_ARGS
        if ffmpeg_threads:
            cmd += ["-threads", str(ffmpeg_threads)]
        cmd += [tmp_out]
        return subprocess.run(cmd, capture_output=True, text=True, encoding="utf-8", errors="replace", timeout=render_timeout_sec(dur))

    label = os.path.basename(out)
    if vf_overlay:
        ok, reason = run_ffmpeg_with_retry(lambda: render(vf_overlay), tmp_out, dur, label)
        if ok:
            return finalize_render(tmp_out, out, True)
        if not _looks_like_drawtext_failure(reason):
            # См. _looks_like_drawtext_failure — таймаут/OOM/др. транзиентный
            # сбой после исчерпанных попыток НЕ повод тихо терять подписи,
            # это честный провал клипа (main() отправит его в missing/повтор).
            print(f"  [{label}] рендер с подписями не удался ({reason}) — "
                  f"это не про drawtext, не откатываюсь на версию без них")
            return finalize_render(tmp_out, out, False)
        # Титр/плашка (drawtext/шрифт) реально недоступны — не повод терять
        # весь кадр. Откат на версию без них (тоже с ретраем/верификацией).
        print(f"  титр/плашка не встали ({label}): {reason} — рисую без них")
    ok, reason = run_ffmpeg_with_retry(lambda: render(vf_base), tmp_out, dur, label)
    if not ok:
        print(f"  [{label}] рендер не удался после {RENDER_RETRY_ATTEMPTS} попыток: {reason}")
    return finalize_render(tmp_out, out, ok)


def media_sidecar_path(media_path):
    """Путь к sidecar-метаданным кэшированного кандидата: <файл>.meta.json."""
    return media_path + ".meta.json"


def read_media_sidecar(media_path):
    """Прочитать sidecar кандидата. Нет файла/битый JSON -> {} (не исключение).

    Отсутствие sidecar — норма для кэша, скачанного ДО появления этого
    механизма: старые файлы просто не дают ID, и дедуп по ID для них работает
    как раньше (никак), а дедуп по aHash считается на месте от самого файла.
    """
    try:
        with open(media_sidecar_path(media_path), "r", encoding="utf-8") as f:
            data = json.load(f)
        return data if isinstance(data, dict) else {}
    except Exception:
        return {}


# Кадрирование источников, у которых пропорция далека от 16:9.
#
# РЕАЛЬНЫЙ, ИЗМЕРЕННЫЙ дефект. Весь пайплайн приводит фото к кадру одним и
# тем же приёмом — increase+crop («залить и обрезать», см. compute_crop_offset
# и fill_crop_canvas ниже). Для стока Pexels (обычно 3:2) это стоит 16%
# высоты и незаметно. Но с подключением музеев, архивов Openverse и Pixabay
# в пул пошёл материал, которого там раньше не было: страницы кодексов,
# надгробные эффигии, доспехи в полный рост, гобелены — то есть ПОРТРЕТНЫЕ
# снимки. Сколько от них остаётся при том же кропе (посчитано геометрией,
# ar/1.778 по высоте):
#
#     миниатюра рукописи 3:4      видно 42%  -> обрезано 58%
#     страница кодекса 2:3        видно 38%  -> обрезано 62%
#     доспех в рост 9:16          видно 32%  -> обрезано 68%
#     квадрат 1:1                 видно 56%  -> обрезано 44%
#
# И это ДО зума Ken Burns, который снимает ещё 8-22%. То есть подлинная
# страница рукописи показывалась зрителю узкой горизонтальной полосой из
# середины — гейты при этом считали кандидата отличным, потому что судили
# по ЦЕЛОМУ изображению, а не по тому, что реально попадёт в кадр.
#
# Решение — стандартное для жанра (и ровно то, что рекомендует продакшн-
# спецификация канала): вписать изображение ЦЕЛИКОМ, а пустоту по бокам
# закрыть размытой и затемнённой копией его же. Затемнение обязательно —
# без него яркая подложка перетягивает внимание с самого кадра.
#
# Порог выбран не на глаз: 4:3 — та пропорция, на которой increase+crop
# теряет ровно четверть высоты. Всё, что ШИРЕ (включая 3:2 Pexels и 16:9),
# идёт прежним путём БАЙТ-В-БАЙТ; подложка появляется только там, где
# обычный кроп уничтожил бы больше четверти кадра.
ASPECT_FIT_MIN_RATIO = 4 / 3


ASPECT_BACKDROP_BLUR = 42        # sigma размытия подложки на холсте 1920x1080


ASPECT_BACKDROP_DARKEN = 0.55    # множитель яркости подложки (документ просит -15%, берём сильнее:


                                  # подложка тут не фон сцены, а заполнение пустоты)
# Передний план вписывается не впритык к краю кадра, а с запасом под зум:
# ZOOM_FLOOR=1.04 уже в первом кадре показывает 96% холста, поэтому при
# полной высоте у страницы рукописи сразу срезался бы верх и низ.
ASPECT_FIT_SAFE = 0.92


ASPECT_FIT_CACHE_DIR = "aspect_fit"


def needs_aspect_backdrop(iw, ih):
    """Нужна ли этому источнику подложка вместо обычного кропа."""
    if not iw or not ih or ih <= 0:
        return False
    return (iw / ih) < ASPECT_FIT_MIN_RATIO


def focus_crop(photo_path):
    """Путь к вырезке вокруг рамки смысловой детали (рамка — в метаданных
    кадра, её ставит locate_focus_box) или исходный путь. Геометрия и кэш —
    focus_frame.crop_file (тот же код у контактного листа); fail-open на
    любую ошибку — слот не пропадает из-за этого шага."""
    if not feature_flags.enabled("FOCUS_CROP"):
        return photo_path
    try:
        box = read_media_sidecar(photo_path).get("focus_box")
        if not box:
            return photo_path
        return focus_frame.crop_file(photo_path, box, os.path.join(TEMP_FOLDER, "focus_crop")) \
            or photo_path
    except Exception:
        return photo_path


def aspect_fit_backdrop(photo_path, out_dir=None, width=None, height=None):
    """Путь к 16:9-версии кадра: сам кадр целиком + размытая тёмная подложка.

    Возвращает ИСХОДНЫЙ путь, если подложка не нужна (кадр 4:3 и шире),
    фича выключена или что-то пошло не так — fail-open, тот же принцип, что
    у остальных опциональных слоёв: ни один слот не должен пропасть из-за
    этого шага. Результат кэшируется по (путь, mtime, размер, параметры),
    поэтому повторный прогон не пересобирает композит."""
    if not feature_flags.enabled("ASPECT_FIT_BACKDROP"):
        return photo_path
    W = width or WIDTH
    H = height or HEIGHT
    try:
        with PILImage.open(photo_path) as probe:
            probe = PILImageOps.exif_transpose(probe)
            iw, ih = probe.size
        if not needs_aspect_backdrop(iw, ih):
            return photo_path
        base = out_dir or os.path.join(TEMP_FOLDER, ASPECT_FIT_CACHE_DIR)
        os.makedirs(base, exist_ok=True)
        key = hashlib.md5("|".join([
            os.path.abspath(photo_path), str(os.path.getmtime(photo_path)),
            str(os.path.getsize(photo_path)), f"{W}x{H}",
            f"{ASPECT_BACKDROP_BLUR}:{ASPECT_BACKDROP_DARKEN}:{ASPECT_FIT_SAFE}",
        ]).encode()).hexdigest()[:12]
        dest = os.path.join(base, f"{key}.jpg")
        if os.path.exists(dest) and os.path.getsize(dest) > 0:
            return dest
        with PILImage.open(photo_path) as im:
            im = PILImageOps.exif_transpose(im).convert("RGB")
            # Подложка: то же изображение, залитое на весь кадр (increase+crop),
            # размытое и притемнённое.
            scale = max(W / im.width, H / im.height)
            bw, bh = max(1, round(im.width * scale)), max(1, round(im.height * scale))
            bg = im.resize((bw, bh), PILImage.LANCZOS).crop(
                ((bw - W) // 2, (bh - H) // 2, (bw - W) // 2 + W, (bh - H) // 2 + H))
            bg = bg.filter(PILImageFilter.GaussianBlur(ASPECT_BACKDROP_BLUR))
            bg = PILImageEnhance.Brightness(bg).enhance(ASPECT_BACKDROP_DARKEN)
            # Передний план: изображение целиком, вписанное с запасом под зум.
            fit = min(W * ASPECT_FIT_SAFE / im.width, H * ASPECT_FIT_SAFE / im.height)
            fw, fh = max(1, round(im.width * fit)), max(1, round(im.height * fit))
            fg = im.resize((fw, fh), PILImage.LANCZOS)
            bg.paste(fg, ((W - fw) // 2, (H - fh) // 2))
            tmp = dest + ".tmp"
            bg.save(tmp, "JPEG", quality=95, subsampling=0)
            os.replace(tmp, dest)
        return dest
    except Exception as e:
        print(f"  подложка 16:9 не собралась для {os.path.basename(str(photo_path))}: {e} — кадрирую как раньше")
        return photo_path


# Мгновенный рез после stat-плашки. Раньше 0.03с — при FPS=24 это 0.72 кадра,
# то есть физически НЕ короче обычного hardcut: ffmpeg всё равно округлял его
# до того же одного кадра. Один кадр — реальный минимум сетки, и теперь это
# написано честно (ветка в плане переходов остаётся отдельной: смысл разный,
# и при другом FPS значения снова разойдутся).
SNAP_CUT_DUR = 1 / FPS


def quantize_dur_to_frame(d):
    """Длительность -> ближайшее целое число кадров (минимум один кадр)."""
    return max(1, int(round(d * FPS))) / FPS


def plan_transitions(sections, blocks=None, xfade_dur=XFADE_DUR):
    """План склейки: [(тип_перехода, длительность), ...] длиной len(sections)-1,
    где элемент j описывает переход между клипами j и j+1.

    ЗАЧЕМ ОТДЕЛЬНАЯ ФУНКЦИЯ (реальный баг, а не рефакторинг ради красоты).
    Раньше тип и длительность перехода выбирались ВНУТРИ xfade_chain() по
    хэшу ПУТЕЙ ФАЙЛОВ клипов. А пути содержат params_hash, в который входит
    длительность клипа (см. main()) — то есть узнать план можно было только
    ПОСЛЕ того, как длительности уже посчитаны. Но длительности считаются
    из бюджета нахлёстов, а бюджет — это и есть сумма плана: замкнутый круг.
    Из-за него estimate_xfade_budget() был вынужден брать ВЕРХНЮЮ ГРАНИЦУ
    "обычной" пары (0.1667с) вместо факта, а факт — 85% одного кадра
    (0.0417с). Перебор ~0.12с на каждой обычной склейке; на 300+ обычных
    склейках 40-минутного эпизода это 35+ секунд, на которые видео
    оказывалось ДЛИННЕЕ аудио. Финальный мукс обрезал их по -t, то есть:
    (1) хвост ролика (несколько последних кадров) не попадал в файл вообще,
    (2) картинка накопительно отставала от голоса — к концу эпизода на
    десятки секунд, при том что весь остальной код (alignment.csv,
    section_sync, snap_hook_cuts_to_energy) борется за точность до
    десятых долей секунды.

    Хэш теперь считается от (номер склейки + имена секций) — данных,
    известных ДО выбора файлов. Разнообразие ровно то же (тот же md5, та же
    статистика), круговая зависимость исчезла, и один и тот же план
    используется и для бюджета, и для реальной склейки, и для расчёта
    визуальных стартов подписей — они физически не могут разойтись.

    Логика ветвления — ровно та, что была в xfade_chain() (переход = сигнал
    драматургии): граница секции -> заметный переход; sub-cut -> один кадр;
    сразу после stat-плашки -> snap; хук -> только жёсткие резы; остальное —
    85% hardcut / 15% короткий диссолв."""
    plan = []
    cut_hist, boundary_hist = [], []
    for i in range(1, len(sections)):
        h = int(hashlib.md5(f"xfade:{i}|{sections[i - 1]}|{sections[i]}".encode()).hexdigest()[:8], 16)
        is_boundary = sections[i] != sections[i - 1]
        b_prev = blocks[i - 1] if blocks else None
        b_cur = blocks[i] if blocks else None
        if is_boundary:
            candidate = BOUNDARY_TRANSITIONS[h % len(BOUNDARY_TRANSITIONS)]
            transition = pick_no_repeat(boundary_hist, candidate, BOUNDARY_TRANSITIONS, 1)
            this_dur = xfade_dur
        elif b_cur is not None and b_cur.get("is_subcut"):
            transition, this_dur = "fade", XFADE_DUR_HARD
        elif b_prev is not None and b_prev.get("stat"):
            transition, this_dur = "fade", SNAP_CUT_DUR
        elif b_cur is not None and sections[i].startswith("HOOK"):
            transition, this_dur = "fade", XFADE_DUR_HARD
        else:
            candidate = "hardcut" if (h % 20 >= 3) else XFADE_TRANSITIONS[(h >> 8) % len(XFADE_TRANSITIONS)]
            choice = pick_no_repeat(cut_hist, candidate, ["hardcut"] + XFADE_TRANSITIONS, max_repeat=3)
            this_dur = XFADE_DUR_HARD if choice == "hardcut" else xfade_dur * 0.4
            transition = "fade" if choice == "hardcut" else choice
        plan.append((transition, quantize_dur_to_frame(this_dur)))
    return plan


def xfade_chain(clips, durs, sections, out, xfade_dur=XFADE_DUR, blocks=None, plan=None):
    """Один проход filter_complex с цепочкой xfade между ВСЕМИ соседними
    кадрами — вместо жёсткой склейки. Переход = сигнал драматургии, не
    случайность: раньше тип перехода выбирался чисто хэшем путей файлов,
    без связи со сменой темы/функции блока — dissolve мог случайно попасть
    внутрь одной фразы, hardcut — между разделами. Теперь мотивированно
    (нужен параллельный список blocks — метаданные клипов, is_subcut/stat/
    section; без него откат на старое хэш-разнообразие для обратной
    совместимости):
    - граница секции → dissolve/fadeblack/fadewhite (смена темы)
    - sub-cut внутри одного исходного блока → только hardcut (это один кадр
      мысли, разрезанный на фазы — не повод анонсировать переход)
    - сразу после клипа со stat-плашкой → snap cut (мгновенный, короче
      обычного hardcut — цифра "впечаталась" и тут же сменилась)
    - весь хук → только hardcut (энергия, скорость, никаких dissolve)
    - остальное — 85% hardcut / 15% короткий dissolve (не полный xfade_dur)
    Возвращает (True, итоговая_длительность) или (False, 0.0), если
    что-то пошло не так (тогда main() откатывается на обычный concat -c copy)."""
    n = len(clips)
    if n < 2:
        return False, 0.0
    # План склейки (тип/длительность каждого перехода) считает plan_transitions()
    # — ОДИН источник истины и для бюджета длительностей, и для этой склейки,
    # и для visual_starts подписей (см. её докстринг про круговую зависимость).
    if plan is None:
        plan = plan_transitions(sections, blocks, xfade_dur=xfade_dur)
    parts, prev_label, cum = [], "0:v", durs[0]
    for i in range(1, n):
        transition, this_dur = plan[i - 1]
        offset = max(0.0, cum - this_dur)
        out_label = f"vx{i}" if i < n - 1 else "vout"
        # .6f, не .3f: offset к концу длинного эпизода — тысячи секунд, и
        # округление до миллисекунд может сдвинуть его на кадр относительно
        # плана (ffmpeg переводит offset в кадры). Полукадр при 24fps — 21мс,
        # запас на порядок больше миллисекунды, но печатать точно ничего не
        # стоит, а гарантия появляется.
        parts.append(f"[{prev_label}][{i}:v]xfade=transition={transition}:"
                     f"duration={this_dur:.6f}:offset={offset:.6f}[{out_label}]")
        cum = cum + durs[i] - this_dur
        prev_label = out_label
    cmd = ["ffmpeg", "-y"]
    for c in clips:
        cmd += ["-i", c]
    # Это единственный проход, который видит ВСЮ склейку сразу — то, что
    # уйдёт на YouTube (финальный мукс делает -c:v copy, второго прохода
    # уже не будет). Каждый отдельный клип и так уже CRF 17 (RENDER_CRF, см.
    # kenburns/video_render/parallax_kenburns) — если тут снова ужать до 23,
    # это второе поколение потерь поверх первого, заметное именно на тёмном
    # грейде (градиенты/дым/зерно). FINAL_PASS_PRESET/CRF — разовая цена, не
    # на каждый маленький клип.
    cmd += ["-filter_complex", ";".join(parts), "-map", "[vout]"] + final_pass_encode_args() + [out]
    # РЕАЛЬНЫЙ пробел, пойманный аудитом того же класса багов, что и
    # SPEED_RAMP_MAX_SOURCE_FPS/parallax stderr-deadlock (см. их докстринги
    # выше): у этого вызова не было НИКАКОГО timeout — при зависании ffmpeg
    # (тот же класс проблем, что и задокументированный ниже "молча роняет
    # кадры и застревает") весь уже отрендеренный за часы прогон терялся бы
    # молча, без единого сигнала. cum — суммарная длительность чанка (до 35
    # клипов на FINAL_PASS_PRESET+FINAL_PASS_CRF (medium+16), тяжелее, чем
    # per-clip RENDER_PRESET+RENDER_CRF (veryfast+17) — щедрый множитель
    # (30x), это последний рубеж защиты от НАСТОЯЩЕГО зависания, не бюджет
    # под скорость.
    try:
        r = subprocess.run(cmd, capture_output=True, text=True, encoding="utf-8", errors="replace",
                            timeout=max(180, cum * 30))
    except subprocess.TimeoutExpired:
        print(f"  xfade-склейка зависла (таймаут {max(180, cum * 30):.0f}с), откат на concat.")
        return False, 0.0
    if r.returncode != 0:
        print("  xfade-склейка не удалась, откат на concat:", r.stderr[-300:])
        return False, 0.0
    # Пойман вживую на 150 клипах (после sub-cuts): ffmpeg возвращает 0
    # (успех), но при очень длинной цепочке последовательных xfade в ОДНОМ
    # filter_complex молча "роняет" кадры (dup=0 drop=20000+ в stderr) и
    # застревает на застывшем кадре с середины ролика — итоговый файл
    # правильной длины (после -shortest/-t на муксе), но 800+ секунд из
    # них заморожены. Return-код тут не индикатор, реальная длительность —
    # индикатор. На ~90 клипах (до sub-cuts) с той же схемой такого не
    # было — это масштабная проблема ffmpeg с очень длинной цепочкой в
    # одном графе, не баг в математике offset/cum (та проверена отдельно).
    try:
        real_dur = get_media_duration(out)
    except Exception:
        real_dur = 0.0
    expected = max(cum, 0.1)
    if real_dur < expected * 0.9 - 2.0:
        print(f"  xfade-склейка вернула 0, но реальная длительность {real_dur:.1f}с "
              f"против ожидаемых {expected:.1f}с (похоже на застревание ffmpeg на "
              f"длинной цепочке xfade) — откат на concat.")
        return False, 0.0
    return True, expected


def get_media_duration(path):
    r = subprocess.run(["ffprobe", "-v", "quiet", "-print_format", "json",
                        "-show_format", path], capture_output=True, text=True, encoding="utf-8", errors="replace", check=True)
    return float(json.loads(r.stdout)["format"]["duration"])


def audio_qc(path, label="Audio QC"):
    """Технический QC дорожки — тот же принцип, что qc_report() для
    картинок: не блокирует, только честно докладывает брак, который иначе
    заметили бы только на слух постфактум (клиппинг, слишком тихо/громко,
    длинные участки мёртвой тишины помимо самих [pause] — забытый обрыв
    записи). Бесплатно — штатные ffmpeg-фильтры astats/silencedetect,
    никакого нового API.

    Вызывается ДВАЖДЫ: на входном голосе (что нам дали) и на ГОТОВОМ
    final.mp4 (что услышит зритель) — см. label. Долгое время проверялся
    только вход, и вся мастер-цепочка (обработка голоса, подложка, дакинг,
    loudnorm, лимитер) уходила к зрителю вообще без технической проверки:
    обе реальные поломки музыки в этом проекте нашлись ручными замерами,
    а не отчётом.
    """
    try:
        r = subprocess.run(
            ["ffmpeg", "-nostats", "-i", path, "-af",
             "astats=reset=0,silencedetect=noise=-40dB:d=1.5", "-f", "null", "-"],
            capture_output=True, text=True, encoding="utf-8", errors="replace",
            # Тот же класс, что чинил аудит 04.09 у measure_loudnorm_stats():
            # фиксированные 120 с — это полный декод, на часовом эпизоде он
            # не укладывается, и QC молча не выполнялся вообще.
            timeout=max(120, int(_audio_len_for_timeout(path) * 0.5)))
        err = r.stderr
    except Exception as e:
        print(f"  {label}: не удалось проверить ({e})")
        return
    warns = []
    m = re.search(r"Peak level dB:\s*(-?[\d.]+)", err)
    if m and float(m.group(1)) > -0.1:
        warns.append(f"пик {m.group(1)} dBFS — на грани клиппинга")
    m = re.search(r"RMS level dB:\s*(-?[\d.]+)", err)
    rms = float(m.group(1)) if m else None
    if rms is not None and rms < -35:
        warns.append(f"RMS {rms:.1f} dBFS — очень тихо")
    elif rms is not None and rms > -12:
        warns.append(f"RMS {rms:.1f} dBFS — очень громко/пережато")
    silences = [float(x) for x in re.findall(r"silence_duration:\s*([\d.]+)", err)]
    if silences:
        try:
            dur = get_media_duration(path)
            ratio = sum(silences) / dur
            if ratio > 0.15:
                warns.append(f"{ratio*100:.0f}% дорожки — тишина длиннее 1.5с (мёртвый воздух?)")
        except Exception:
            pass
    print(f"{label}: {'; '.join(warns)}" if warns
          else f"{label}: клиппинга/аномальной громкости не найдено")


def build_master_af(loud_stats, fade_out_st, fade_in_sec):
    """Мастер-цепочка финального прохода: loudnorm -> лимитер -> фейды.

    Вынесено из main() отдельной функцией, чтобы порядок ступеней можно было
    проверить тестом, а не только прочитать. Порядок здесь — не вкусовщина:

    * лимитер ПОСЛЕ loudnorm — иначе loudnorm поднял бы уровень уже после
      того, как потолок выставлен, и потолок перестал бы быть потолком;
    * лимитер ПЕРЕД afade — afade только уменьшает уровень, так что на
      результат он не влияет, но обратный порядок заставил бы лимитер
      работать на затухающих хвостах, где он бесполезен;
    * порог лимитера — та же константа LOUDNORM_TARGET_TP, что цель true
      peak у loudnorm: две ступени не должны спорить о потолке.

    loud_stats=None — первый проход не измерился, идём однопроходным
    (динамическим) loudnorm; это уже существующий откат, лимитер в нём
    тем более уместен.
    """
    base = f"loudnorm=I={LOUDNORM_TARGET_I}:TP={LOUDNORM_TARGET_TP}:LRA={LOUDNORM_TARGET_LRA}"
    if loud_stats:
        base += (f":linear=true:measured_I={loud_stats['input_i']}:"
                 f"measured_TP={loud_stats['input_tp']}:"
                 f"measured_LRA={loud_stats['input_lra']}:"
                 f"measured_thresh={loud_stats['input_thresh']}:"
                 f"offset={loud_stats['target_offset']}")
    stages = [base]
    if MASTER_LIMITER_ENABLED:
        stages.append(f"alimiter=limit={LOUDNORM_TARGET_TP}dB:"
                      f"attack={MASTER_LIMITER_ATTACK_MS}:"
                      f"release={MASTER_LIMITER_RELEASE_MS}:level=disabled")
    stages.append(f"afade=t=in:st=0:d={fade_in_sec}")
    stages.append(f"afade=t=out:st={fade_out_st:.3f}:d=2")
    return ",".join(stages)


def write_audio_master_report(video_dir, final_lufs=None):
    """media_plan/audio_master_report.json — чем собран звук этого ролика.

    Ровно тот же принцип, что feature_flags.json для видео: по готовому
    файлу должно быть можно ответить, какой была подложка и почему, а не
    вспоминать. Особенно теперь, когда усиление подложки не константа в
    исходнике, а результат измерения на месте (music_bed_gain_db()).
    """
    payload = {
        "music_enabled": bool(MUSIC_ENABLED),
        "bed": MUSIC_BED_DECISION,
        "target_gap_lu": MUSIC_BED_GAP_LU,
        "duck": {"threshold": MUSIC_DUCK_THRESHOLD, "ratio": MUSIC_DUCK_RATIO,
                 "attack_ms": MUSIC_DUCK_ATTACK_MS, "release_ms": MUSIC_DUCK_RELEASE_MS},
        "climax_dip_db": CLIMAX_DIP_DB,
        "voice_process_enabled": bool(VOICE_PROCESS_ENABLED),
        "limiter": ({"limit_db": LOUDNORM_TARGET_TP,
                     "attack_ms": MASTER_LIMITER_ATTACK_MS,
                     "release_ms": MASTER_LIMITER_RELEASE_MS}
                    if MASTER_LIMITER_ENABLED else None),
        "loudnorm": {"I": LOUDNORM_TARGET_I, "TP": LOUDNORM_TARGET_TP,
                     "LRA": LOUDNORM_TARGET_LRA},
        "final_lufs": final_lufs,
    }
    try:
        path = os.path.join(video_dir, "media_plan", "audio_master_report.json")
        os.makedirs(os.path.dirname(path), exist_ok=True)
        tmp = path + ".tmp"
        with open(tmp, "w", encoding="utf-8") as f:
            json.dump(payload, f, ensure_ascii=False, indent=1)
        os.replace(tmp, path)
        return path
    except Exception as e:
        # Отчёт вспомогательный: потерять готовый ролик из-за него было бы
        # хуже, чем остаться без него (тот же fail-open, что у sidecar).
        print(f"  ВНИМАНИЕ: audio_master_report не записан ({type(e).__name__})")
        return None


# Фильтры ffmpeg, без которых включённый слой не соберёт НИ ОДНОГО клипа.
# Ключ — имя флага реестра, значение — фильтры, которые этот слой реально
# вызывает. Проверяются только ВКЛЮЧЁННЫЕ слои: выключенный deflicker на
# сборке без deflicker не проблема.
REQUIRED_FFMPEG_FILTERS = {
    None:                ("zoompan", "xfade", "scale"),   # ядро, всегда
    "ON_SCREEN_TEXT":    ("drawtext",),
    "GRAIN_ENABLED":     ("blend",),
    "DEFLICKER_ENABLED": ("deflicker",),
    "MUSIC_BED":         ("sidechaincompress", "loudnorm"),
}


_FFMPEG_FILTERS_CACHE = None


def available_ffmpeg_filters():
    """Множество имён фильтров у ТОГО ffmpeg, который реально будет вызван."""
    global _FFMPEG_FILTERS_CACHE
    if _FFMPEG_FILTERS_CACHE is not None:
        return _FFMPEG_FILTERS_CACHE
    try:
        out = subprocess.run(["ffmpeg", "-hide_banner", "-filters"],
                             capture_output=True, text=True, encoding="utf-8",
                             errors="replace", timeout=30).stdout
        _FFMPEG_FILTERS_CACHE = set(re.findall(r'^\s*[A-Z.]{3}\s+(\S+)', out, re.M))
    except Exception:
        _FFMPEG_FILTERS_CACHE = set()   # не смогли спросить — не гейтим
    return _FFMPEG_FILTERS_CACHE


def check_ffmpeg_filters():
    """Назвать отсутствующий фильтр ДО рендера, а не после трёх попыток.

    Реальный случай 14.09, стоивший целого прогона: в контейнере ffmpeg шёл
    из imageio-ffmpeg (символьная ссылка /usr/local/bin/ffmpeg), собранного
    БЕЗ drawtext — ffmpeg 7 требует для него libharfbuzz. Каждый клип с
    плашкой/титром падал с 'Filter not found', три попытки подряд, и только
    RENDER_STRICT_GATE не дал собрать ролик молча без экранного текста.
    Сообщение при этом не называло НИ отсутствующий фильтр (его имя тонуло
    в эхе всего filter_complex), НИ причину — диагностика заняла больше,
    чем сам рендер.

    Ничего не блокирует: печатает предупреждение и возвращает список — тот
    же fail-open, что у остальных проверок окружения. Сборка всё равно
    остановится на RENDER_STRICT_GATE, но теперь с названной причиной."""
    have = available_ffmpeg_filters()
    if not have:
        return []
    missing = []
    for flag, filters in REQUIRED_FFMPEG_FILTERS.items():
        if flag is not None and not feature_flags.enabled(flag):
            continue
        for f in filters:
            if f not in have:
                missing.append((f, flag or "ядро рендера"))
    if missing:
        print("  ВНИМАНИЕ: у этого ffmpeg НЕТ фильтров, которые нужны включённым слоям:")
        for f, flag in missing:
            print(f"    {f} — нужен для {flag}")
        print("    Клипы с этим слоем упадут с 'Filter not found'. Поставить сборку"
              " ffmpeg с этими фильтрами (например системный пакет вместо"
              " imageio-ffmpeg) либо выключить слой в .env.")
    return missing




def configure(video_dir):
    """Папка ролика для всех функций модуля (в исходнике — sys.argv[1] на
    импорте). Сбрасывает кэши, привязанные к папке."""
    global VIDEO_FOLDER, TEMP_FOLDER, OUTPUT_FILE, ALIGNMENT_DIR, PAUSE_CUTS_PATH
    global SECTION_OFFSETS_PATH, _PAUSE_CUTS_CACHE, _PAUSE_INSERTS_CACHE, _PAUSE_WINDOWS_CACHE
    global _SECTION_OFFSETS_CACHE, SPEECH_ENDS, ALIGNMENT_ONSET_FAILURE, MUSIC_BED_DECISION
    VIDEO_FOLDER = os.path.abspath(video_dir)
    TEMP_FOLDER = os.path.join(VIDEO_FOLDER, "temp_render")
    OUTPUT_FILE = os.path.join(VIDEO_FOLDER, "final.mp4")
    ALIGNMENT_DIR = os.path.join(VIDEO_FOLDER, "media_plan", "alignment")
    PAUSE_CUTS_PATH = os.path.join(VIDEO_FOLDER, "media_plan", "pause_cuts.json")
    SECTION_OFFSETS_PATH = os.path.join(VIDEO_FOLDER, "media_plan", "section_offsets.json")
    _PAUSE_CUTS_CACHE = _PAUSE_INSERTS_CACHE = _PAUSE_WINDOWS_CACHE = None
    _SECTION_OFFSETS_CACHE = None
    SPEECH_ENDS = []
    ALIGNMENT_ONSET_FAILURE = None
    MUSIC_BED_DECISION = None
    os.makedirs(TEMP_FOLDER, exist_ok=True)
